INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,48,'Ar-Rahmaan','ذَوَاتَآ أَفۡنَانࣲ‏','ان دونوں میں بہت سی شاخیں (یعنی قسم قسم کے میووں کے درخت ہیں)','˹Both will be˺ with lush branches','दोनों बाग़ (दरख्तों की) टहनियों से हरे भरे (मेवों से लदे) हुए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,49,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','फिर दोनों अपने सरपरस्त की किस किस नेअमतों को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,50,'Ar-Rahmaan','فِيهِمَا عَيۡنَانِ تَجۡرِيَانِ','ان میں دو چشمے بہہ رہے ہیں','In each ˹Garden˺ will be two flowing springs','इन दोनों में दो चश्में जारी होंगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,51,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने परवरदिगार की किस किस नेअमत से मुकरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,52,'Ar-Rahmaan','فِيهِمَا مِن كُلِّ فَٰكِهَةࣲ زَوۡجَانِ','ان میں سب میوے دو دو قسم کے ہیں','In each will be two types of every fruit','इन दोनों बाग़ों में सब मेवे दो दो किस्म के होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,53,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तुम दोनों अपने परवरदिगार की किस किस नेअमत से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,54,'Ar-Rahmaan','مُتَّكِـِٔينَ عَلَىٰ فُرُشِۭ بَطَآئِنُهَا مِنۡ إِسۡتَبۡرَقࣲۚ وَجَنَى ٱلۡجَنَّتَيۡنِ دَانࣲ‏','(اہل جنت) ایسے بچھونوں پر جن کے استرا طلس کے ہیں تکیہ لگائے ہوئے ہوں گے۔ اور دونوں باغوں کے میوے قریب (جھک رہے) ہیں','Those ˹believers˺ will recline on furnishings lined with rich brocade. And the fruit of both Gardens will hang within reach','यह लोग उन फ़र्शों पर जिनके असतर अतलस के होंगे तकिये लगाकर बैठे होंगे तो दोनों बाग़ों के मेवे (इस क़दर) क़रीब होंगे (कि अगर चाहे तो लगे हुए खालें)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,55,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने मालिक की किस किस नेअमत को न मानोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,56,'Ar-Rahmaan','فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرۡفِ لَمۡ يَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَآنࣱّ‏','ان میں نیچی نگاہ والی عورتیں ہیں جن کو اہل جنت سے پہلے نہ کسی انسان نے ہاتھ لگایا اور نہ کسی جن نے','In both ˹Gardens˺ will be maidens of modest gaze, who no human or jinn has ever touched before','इसमें (पाक दामन ग़ैर की तरफ ऑंख उठा कर न देखने वाली औरतें होंगी जिनको उन से पहले न किसी इन्सान ने हाथ लगाया होगा) और जिन ने');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,57,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने परवरदिगार की किन किन नेअमतों को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,58,'Ar-Rahmaan','كَأَنَّهُنَّ ٱلۡيَاقُوتُ وَٱلۡمَرۡجَانُ','گویا وہ یاقوت اور مرجان ہیں','Those ˹maidens˺ will be ˹as elegant˺ as rubies and coral','(ऐसी हसीन) गोया वह (मुजस्सिम) याक़ूत व मूँगे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,59,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने परवरदिगार की किन किन नेअमतों से मुकरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,60,'Ar-Rahmaan','هَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ','نیکی کا بدلہ نیکی کے سوا کچھ نہیں ہے','Is there any reward for goodness except goodness','भला नेकी का बदला नेकी के सिवा कुछ और भी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,61,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','फिर तुम दोनों अपने मालिक की किस किस नेअमत को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,62,'Ar-Rahmaan','وَمِن دُونِهِمَا جَنَّتَانِ','اور ان باغوں کے علاوہ دو باغ اور ہیں','And below these two ˹Gardens˺ will be two others','उन दोनों बाग़ों के अलावा दो बाग़ और हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,63,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने पालने वाले की किस किस नेअमत से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,64,'Ar-Rahmaan','مُدۡهَآمَّتَانِ','دونوں خوب گہرے سبز','Both will be dark green','दोनों निहायत गहरे सब्ज़ व शादाब');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,65,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने सरपरस्त की किन किन नेअमतों को न मानोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,66,'Ar-Rahmaan','فِيهِمَا عَيۡنَانِ نَضَّاخَتَانِ','ان میں دو چشمے ابل رہے ہیں','In each will be two gushing springs','उन दोनों बाग़ों में दो चश्में जोश मारते होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,67,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने परवरदिगार की किस किस नेअमत से मुकरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,68,'Ar-Rahmaan','فِيهِمَا فَٰكِهَةࣱ وَنَخۡلࣱ وَرُمَّانࣱ‏','ان میں میوے اور کھجوریں اور انار ہیں','In both will be fruit, palm trees, and pomegranates','उन दोनों में मेवें हैं खुरमें और अनार');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,69,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने मालिक की किन किन नेअमतों को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,70,'Ar-Rahmaan','فِيهِنَّ خَيۡرَٰتٌ حِسَانࣱ‏','ان میں نیک سیرت (اور) خوبصورت عورتیں ہیں','In all Gardens will be noble, pleasant mates','उन बाग़ों में ख़ुश ख़ुल्क और ख़ूबसूरत औरतें होंगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,71,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','तो तुम दोनों अपने मालिक की किन किन नेअमतों को झुठलाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,72,'Ar-Rahmaan','حُورࣱ مَّقۡصُورَٰتࣱ فِي ٱلۡخِيَامِ','(وہ) حوریں (ہیں جو) خیموں میں مستور (ہیں)','˹They will be˺ maidens with gorgeous eyes, reserved in pavilions','वह हूरें हैं जो ख़ेमों में छुपी बैठी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,73,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','फिर तुम दोनों अपने परवरदिगार की कौन कौन सी नेअमत से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,74,'Ar-Rahmaan','لَمۡ يَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَآنࣱّ‏','ان کو اہل جنت سے پہلے نہ کسی انسان نے ہاتھ لگایا اور نہ کسی جن نے','No human or jinn has ever touched these ˹maidens˺ before','उनसे पहले उनको किसी इन्सान ने उनको छुआ तक नहीं और न जिन ने');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,75,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','फिर तुम दोनों अपने मालिक की किस किस नेअमत से मुकरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,76,'Ar-Rahmaan','مُتَّكِـِٔينَ عَلَىٰ رَفۡرَفٍ خُضۡرࣲ وَعَبۡقَرِيٍّ حِسَانࣲ‏','سبز قالینوں اور نفیس مسندوں پر تکیہ لگائے بیٹھے ہوں گے','All ˹believers˺ will be reclining on green cushions and splendid carpets','ये लोग सब्ज़ कालीनों और नफीस व हसीन मसनदों पर तकिए लगाए (बैठे) होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,77,'Ar-Rahmaan','فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ','تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟','Then which of your Lord’s favours will you both deny','फिर तुम अपने परवरदिगार की किन किन नेअमतों से इन्कार करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (55,78,'Ar-Rahmaan','تَبَٰرَكَ ٱسۡمُ رَبِّكَ ذِي ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ','(اے محمدﷺ) تمہارا پروردگار جو صاحب جلال وعظمت ہے اس کا نام بڑا بابرکت ہے','Blessed is the Name of your Lord, full of Majesty and Honour','(ऐ रसूल) तुम्हारा परवरदिगार जो साहिबे जलाल व करामत है उसी का नाम बड़ा बाबरकत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,1,'Al-Waaqia','إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ','جب واقع ہونے والی واقع ہوجائے','When the Inevitable Event takes place','जब क़यामत बरपा होगी और उसके वाक़िया होने में ज़रा झूट नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,2,'Al-Waaqia','لَيۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ','اس کے واقع ہونے میں کچھ جھوٹ نہیں','then no one can deny it has come','उस वक्त लोगों में फ़र्क ज़ाहिर होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,3,'Al-Waaqia','خَافِضَةࣱ رَّافِعَةٌ','کسی کو پست کرے کسی کو بلند','It will debase ˹some˺ and elevate ˹others˺','कि किसी को पस्त करेगी किसी को बुलन्द');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,4,'Al-Waaqia','إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجࣰّ ا','جب زمین بھونچال سے لرزنے لگے','When the earth will be violently shaken','जब ज़मीन बड़े ज़ोरों में हिलने लगेगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,5,'Al-Waaqia','وَبُسَّتِ ٱلۡجِبَالُ بَسࣰّ ا','اور پہاڑ ٹوٹ کر ریزہ ریزہ ہوجائیں','and the mountains will be crushed to pieces','और पहाड़ (टकरा कर) बिल्कुल चूर चूर हो जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,6,'Al-Waaqia','فَكَانَتۡ هَبَآءࣰ مُّنۢبَثࣰّ ا','پھر غبار ہو کر اُڑنے لگیں','becoming scattered ˹particles of˺ dust','फिर ज़र्रे बन कर उड़ने लगेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,7,'Al-Waaqia','وَكُنتُمۡ أَزۡوَٰجࣰ ا ثَلَٰثَةࣰ‏','اور تم لوگ تین قسم ہوجاؤ','you will ˹all˺ be ˹divided into˺ three groups','और तुम लोग तीन किस्म हो जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,8,'Al-Waaqia','فَأَصۡحَٰبُ ٱلۡمَيۡمَنَةِ مَآ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ','تو داہنے ہاتھ والے (سبحان الله) داہنے ہاتھ والے کیا (ہی چین میں) ہیں','the people of the right, how ˹blessed˺ will they be','तो दाहिने हाथ (में आमाल नामा लेने) वाले (वाह) दाहिने हाथ वाले क्या (चैन में) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,9,'Al-Waaqia','وَأَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ مَآ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ','اور بائیں ہاتھ والے (افسوس) بائیں ہاتھ والے کیا (گرفتار عذاب) ہیں','the people of the left, how ˹miserable˺ will they be','और बाएं हाथ (में आमाल नामा लेने) वाले (अफ़सोस) बाएं हाथ वाले क्या (मुसीबत में) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,10,'Al-Waaqia','وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ','اور جو آگے بڑھنے والے ہیں (ان کا کیا کہنا) وہ آگے ہی بڑھنے والے ہیں','and the foremost ˹in faith˺ will be the foremost ˹in Paradise˺','और जो आगे बढ़ जाने वाले हैं (वाह क्या कहना) वह आगे ही बढ़ने वाले थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,11,'Al-Waaqia','أُوْلَٰٓئِكَ ٱلۡمُقَرَّبُونَ','وہی (خدا کے) مقرب ہیں','They are the ones nearest ˹to Allah˺','यही लोग (ख़ुदा के) मुक़र्रिब हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,12,'Al-Waaqia','فِي جَنَّٰتِ ٱلنَّعِيمِ','نعمت کے بہشتوں میں','in the Gardens of Bliss','आराम व आसाइश के बाग़ों में बहुत से');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,13,'Al-Waaqia','ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِينَ','وہ بہت سے تو اگلے لوگوں میں سے ہوں گے','˹They will be˺ a multitude from earlier generations','तो अगले लोगों में से होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,14,'Al-Waaqia','وَقَلِيلࣱ مِّنَ ٱلۡأٓخِرِينَ','اور تھوڑے سے پچھلوں میں سے','and a few from later generations','और कुछ थोडे से पिछले लोगों में से मोती');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,15,'Al-Waaqia','عَلَىٰ سُرُرࣲ مَّوۡضُونَةࣲ‏','(لعل و یاقوت وغیرہ سے) جڑے ہوئے تختوں پر','˹All will be˺ on jewelled thrones','और याक़ूत से जड़े हुए सोने के तारों से बने हुए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,16,'Al-Waaqia','مُّتَّكِـِٔينَ عَلَيۡهَا مُتَقَٰبِلِينَ','آمنے سامنے تکیہ لگائے ہوئے','reclining face to face','तख्ते पर एक दूसरे के सामने तकिए लगाए (बैठे) होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,17,'Al-Waaqia','يَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنࣱ مُّخَلَّدُونَ','نوجوان خدمت گزار جو ہمیشہ (ایک ہی حالت میں) رہیں گے ان کے آس پاس پھریں گے','They will be waited on by eternal youths','नौजवान लड़के जो (बेहिश्त में) हमेशा (लड़के ही बने) रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,18,'Al-Waaqia','بِأَكۡوَابࣲ وَأَبَارِيقَ وَكَأۡسࣲ مِّن مَّعِينࣲ‏','یعنی آبخورے اور آفتابے اور صاف شراب کے گلاس لے لے کر','with cups, pitchers, and a drink ˹of pure wine˺ from a flowing stream','(शरबत वग़ैरह के) सागर और चमकदार टोंटीदार कंटर और शफ्फ़ाफ़ शराब के जाम लिए हुए उनके पास चक्कर लगाते होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,19,'Al-Waaqia','لَّا يُصَدَّعُونَ عَنۡهَا وَلَا يُنزِفُونَ','اس سے نہ تو سر میں درد ہوگا اور نہ ان کی عقلیں زائل ہوں گی','that will cause them neither headache nor intoxication','जिसके (पीने) से न तो उनको (ख़ुमार से) दर्दसर होगा और न वह बदहवास मदहोश होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,20,'Al-Waaqia','وَفَٰكِهَةࣲ مِّمَّا يَتَخَيَّرُونَ','اور میوے جس طرح کے ان کو پسند ہوں','˹They will also be served˺ any fruit they choose','और जिस क़िस्म के मेवे पसन्द करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,21,'Al-Waaqia','وَلَحۡمِ طَيۡرࣲ مِّمَّا يَشۡتَهُونَ','اور پرندوں کا گوشت جس قسم کا ان کا جی چاہے','and meat from any bird they desire','और जिस क़िस्म के परिन्दे का गोश्त उनका जी चाहे (सब मौजूद है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,22,'Al-Waaqia','وَحُورٌ عِينࣱ‏','اور بڑی بڑی آنکھوں والی حوریں','And ˹they will have˺ maidens with gorgeous eyes','और बड़ी बड़ी ऑंखों वाली हूरें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,23,'Al-Waaqia','كَأَمۡثَٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ','جیسے (حفاظت سے) تہہ کئے ہوئے (آب دار) موتی','like pristine pearls','जैसे एहतेयात से रखे हुए मोती');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,24,'Al-Waaqia','جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ','یہ ان اعمال کا بدلہ ہے جو وہ کرتے تھے','˹all˺ as a reward for what they used to do','ये बदला है उनके (नेक) आमाल का');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,25,'Al-Waaqia','لَا يَسۡمَعُونَ فِيهَا لَغۡوࣰ ا وَلَا تَأۡثِيمًا','وہاں نہ بیہودہ بات سنیں گے اور نہ گالی گلوچ','There they will never hear any idle or sinful talk—','वहाँ न तो बेहूदा बात सुनेंगे और न गुनाह की बात');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,26,'Al-Waaqia','إِلَّا قِيلࣰ ا سَلَٰمࣰ ا سَلَٰمࣰ ا','ہاں ان کا کلام سلام سلام (ہوگا)','only good and virtuous speech','(फहश) बस उनका कलाम सलाम ही सलाम होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,27,'Al-Waaqia','وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ أَصۡحَٰبُ ٱلۡيَمِينِ','اور داہنے ہاتھ والے (سبحان الله) داہنے ہاتھ والے کیا (ہی عیش میں) ہیں','And the people of the right—how ˹blessed˺ will they be','और दाहिने हाथ वाले (वाह) दाहिने हाथ वालों का क्या कहना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,28,'Al-Waaqia','فِي سِدۡرࣲ مَّخۡضُودࣲ‏','(یعنی) بےخار کی بیریوں','˹They will be˺ amid thornless lote trees','बे काँटे की बेरो और लदे गुथे हुए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,29,'Al-Waaqia','وَطَلۡحࣲ مَّنضُودࣲ‏','اور تہہ بہ تہہ کیلوں','clusters of bananas','केलों और लम्बी लम्बी छाँव');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,30,'Al-Waaqia','وَظِلࣲّ مَّمۡدُودࣲ‏','اور لمبے لمبے سایوں','extended shade','और झरनो के पानी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,31,'Al-Waaqia','وَمَآءࣲ مَّسۡكُوبࣲ‏','اور پانی کے جھرنوں','flowing water','और अनारों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,32,'Al-Waaqia','وَفَٰكِهَةࣲ كَثِيرَةࣲ‏','اور میوہ ہائے کثیرہ (کے باغوں) میں','abundant fruit—','मेवो में होंगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,33,'Al-Waaqia','لَّا مَقۡطُوعَةࣲ وَلَا مَمۡنُوعَةࣲ‏','جو نہ کبھی ختم ہوں اور نہ ان سے کوئی روکے','never out of season nor forbidden—','जो न कभी खत्म होंगे और न उनकी कोई रोक टोक');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,34,'Al-Waaqia','وَفُرُشࣲ مَّرۡفُوعَةٍ','اور اونچے اونچے فرشوں میں','and elevated furnishings','और ऊँचे ऊँचे (नरम गद्दो के) फ़र्शों में (मज़े करते) होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,35,'Al-Waaqia','إِنَّآ أَنشَأۡنَٰهُنَّ إِنشَآءࣰ‏','ہم نے ان (حوروں) کو پیدا کیا','Indeed, We will have perfectly created their mates','(उनको) वह हूरें मिलेंगी जिसको हमने नित नया पैदा किया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,36,'Al-Waaqia','فَجَعَلۡنَٰهُنَّ أَبۡكَارًا','تو ان کو کنواریاں بنایا','making them virgins','तो हमने उन्हें कुँवारियाँ प्यारी प्यारी हमजोलियाँ बनाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,37,'Al-Waaqia','عُرُبًا أَتۡرَابࣰ ا','(اور شوہروں کی) پیاریاں اور ہم عمر','loving and of equal age','ये सब सामान');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,38,'Al-Waaqia','لِّأَصۡحَٰبِ ٱلۡيَمِينِ','یعنی داہنے ہاتھ والوں کے لئے','for the people of the right','दाहिने हाथ (में नामए आमाल लेने) वालों के वास्ते है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,39,'Al-Waaqia','ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِينَ','(یہ) بہت سے اگلے لوگوں میں سے ہیں','˹who will be˺ a multitude from earlier generations','(इनमें) बहुत से तो अगले लोगों में से');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,40,'Al-Waaqia','وَثُلَّةࣱ مِّنَ ٱلۡأٓخِرِينَ','اور بہت سے پچھلوں میں سے','and a multitude from later generations','और बहुत से पिछले लोगों में से');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,41,'Al-Waaqia','وَأَصۡحَٰبُ ٱلشِّمَالِ مَآ أَصۡحَٰبُ ٱلشِّمَالِ','اور بائیں ہاتھ والے (افسوس) بائیں ہاتھ والے کیا (ہی عذاب میں) ہیں','And the people of the left—how ˹miserable˺ will they be','और बाएं हाथ (में नामए आमाल लेने) वाले (अफसोस) बाएं हाथ वाले क्या (मुसीबत में) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,42,'Al-Waaqia','فِي سَمُومࣲ وَحَمِيمࣲ‏','(یعنی دوزخ کی) لپٹ اور کھولتے ہوئے پانی میں','˹They will be˺ in scorching heat and boiling water','(दोज़ख़ की) लौ और खौलते हुए पानी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,43,'Al-Waaqia','وَظِلࣲّ مِّن يَحۡمُومࣲ‏','اور سیاہ دھوئیں کے سائے میں','in the shade of black smoke','और काले सियाह धुएँ के साये में होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,44,'Al-Waaqia','لَّا بَارِدࣲ وَلَا كَرِيمٍ','(جو) نہ ٹھنڈا (ہے) نہ خوشنما','neither cool nor refreshing','जो न ठन्डा और न ख़ुश आइन्द');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,45,'Al-Waaqia','إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُتۡرَفِينَ','یہ لوگ اس سے پہلے عیشِ نعیم میں پڑے ہوئے تھے','Indeed, before this ˹torment˺ they were spoiled by luxury','ये लोग इससे पहले (दुनिया में) ख़ूब ऐश उड़ा चुके थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,46,'Al-Waaqia','وَكَانُواْ يُصِرُّونَ عَلَى ٱلۡحِنثِ ٱلۡعَظِيمِ','اور گناہ عظیم پر اڑے ہوئے تھے','and persisted in the worst of sin','और बड़े गुनाह (शिर्क) पर अड़े रहते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,47,'Al-Waaqia','وَكَانُواْ يَقُولُونَ أَئِذَا مِتۡنَا وَكُنَّا تُرَابࣰ ا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ','اور کہا کرتے تھے کہ بھلا جب ہم مرگئے اور مٹی ہوگئے اور ہڈیاں (ہی ہڈیاں رہ گئے) تو کیا ہمیں پھر اُٹھنا ہوگا؟','They used to ask ˹mockingly˺, “When we are dead and reduced to dust and bones, will we really be resurrected','और कहा करते थे कि भला जब हम मर जाएँगे और (सड़ गल कर) मिटटी और हडिडयाँ (ही हडिडयाँ) रह जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,48,'Al-Waaqia','أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ','اور کیا ہمارے باپ دادا کو بھی؟','And our forefathers as well?”','तो क्या हमें या हमारे अगले बाप दादाओं को फिर उठना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,49,'Al-Waaqia','قُلۡ إِنَّ ٱلۡأَوَّلِينَ وَٱلۡأٓخِرِينَ','کہہ دو کہ بےشک پہلے اور پچھلے','Say, ˹O Prophet,˺ “Most certainly, earlier and later generations','(ऐ रसूल) तुम कह दो कि अगले और पिछले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,50,'Al-Waaqia','لَمَجۡمُوعُونَ إِلَىٰ مِيقَٰتِ يَوۡمࣲ مَّعۡلُومࣲ‏','(سب) ایک روز مقرر کے وقت پر جمع کئے جائیں گے','will surely be gathered ˹together˺ for the appointed Day','सब के सब रोजे मुअय्यन की मियाद पर ज़रूर इकट्ठे किए जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,51,'Al-Waaqia','ثُمَّ إِنَّكُمۡ أَيُّهَا ٱلضَّآلُّونَ ٱلۡمُكَذِّبُونَ','پھر تم اے جھٹلانے والے گمرا ہو','Then you, O misguided deniers','फिर तुमको बेशक ऐ गुमराहों झुठलाने वालों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,52,'Al-Waaqia','لَأٓكِلُونَ مِن شَجَرࣲ مِّن زَقُّومࣲ‏','تھوہر کے درخت کھاؤ گے','will certainly eat from ˹the fruit of˺ the trees of Zaqqûm','यक़ीनन (जहन्नुम में) थोहड़ के दरख्तों में से खाना होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,53,'Al-Waaqia','فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ','اور اسی سے پیٹ بھرو گے','filling up ˹your˺ bellies with it','तो तुम लोगों को उसी से (अपना) पेट भरना होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,54,'Al-Waaqia','فَشَٰرِبُونَ عَلَيۡهِ مِنَ ٱلۡحَمِيمِ','اور اس پر کھولتا ہوا پانی پیو گے','Then on top of that you will drink boiling water—','फिर उसके ऊपर खौलता हुआ पानी पीना होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,55,'Al-Waaqia','فَشَٰرِبُونَ شُرۡبَ ٱلۡهِيمِ','اور پیو گے بھی تو اس طرح جیسے پیاسے اونٹ پیتے ہیں','and you will drink ˹it˺ like thirsty camels do.”','और पियोगे भी तो प्यासे ऊँट का सा (डग डगा के) पीना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,56,'Al-Waaqia','هَٰذَا نُزُلُهُمۡ يَوۡمَ ٱلدِّينِ','جزا کے دن یہ ان کی ضیافت ہوگی','This will be their accommodation on the Day of Judgment','क़यामत के दिन यही उनकी मेहमानी होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,57,'Al-Waaqia','نَحۡنُ خَلَقۡنَٰكُمۡ فَلَوۡلَا تُصَدِّقُونَ','ہم نے تم کو (پہلی بار بھی تو) پیدا کیا ہے تو تم (دوبارہ اُٹھنے کو) کیوں سچ نہیں سمجھتے؟','It is We Who created you. Will you not then believe ˹in resurrection˺','तुम लोगों को (पहली बार भी) हम ही ने पैदा किया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,58,'Al-Waaqia','أَفَرَءَيۡتُم مَّا تُمۡنُونَ','دیکھو تو کہ جس (نطفے) کو تم (عورتوں کے رحم میں) ڈالتے ہو','Have you considered what you ejaculate','फिर तुम लोग (दोबार की) क्यों नहीं तस्दीक़ करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,59,'Al-Waaqia','ءَأَنتُمۡ تَخۡلُقُونَهُۥٓ أَمۡ نَحۡنُ ٱلۡخَٰلِقُونَ','کیا تم اس (سے انسان) کو بناتے ہو یا ہم بناتے ہیں؟','Is it you who create ˹a child out of˺ it, or is it We Who do so','तो जिस नुत्फे क़ो तुम (औरतों के रहम में डालते हो) क्या तुमने देख भाल लिया है क्या तुम उससे आदमी बनाते हो या हम बनाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,60,'Al-Waaqia','نَحۡنُ قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِينَ','ہم نے تم میں مرنا ٹھہرا دیا ہے اور ہم اس (بات) سے عاجز نہیں','We have ordained death for ˹all of˺ you, and We cannot be prevented','हमने तुम लोगों में मौत को मुक़र्रर कर दिया है और हम उससे आजिज़ नहीं हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,61,'Al-Waaqia','عَلَىٰٓ أَن نُّبَدِّلَ أَمۡثَٰلَكُمۡ وَنُنشِئَكُمۡ فِي مَا لَا تَعۡلَمُونَ','کہ تمہاری طرح کے اور لوگ تمہاری جگہ لے آئیں اور تم کو ایسے جہان میں جس کو تم نہیں جانتے پیدا کر دیں','from transforming and recreating you in forms unknown to you','कि तुम्हारे ऐसे और लोग बदल डालें और तुम लोगों को इस (सूरत) में पैदा करें जिसे तुम मुत्तलक़ नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,62,'Al-Waaqia','وَلَقَدۡ عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ','اور تم نے پہلی پیدائش تو جان ہی لی ہے۔ پھر تم سوچتے کیوں نہیں؟','You already know how you were first created. Will you not then be mindful','और तुमने पैहली पैदाइश तो समझ ही ली है (कि हमने की) फिर तुम ग़ौर क्यों नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,63,'Al-Waaqia','أَفَرَءَيۡتُم مَّا تَحۡرُثُونَ','بھلا دیکھو تو کہ جو کچھ تم بوتے ہو','Have you considered what you sow','भला देखो तो कि जो कुछ तुम लोग बोते हो क्या');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,64,'Al-Waaqia','ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّٰرِعُونَ','تو کیا تم اسے اُگاتے ہو یا ہم اُگاتے ہیں؟','Is it you who cause it to grow, or is it We Who do so','तुम लोग उसे उगाते हो या हम उगाते हैं अगर हम चाहते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,65,'Al-Waaqia','لَوۡ نَشَآءُ لَجَعَلۡنَٰهُ حُطَٰمࣰ ا فَظَلۡتُمۡ تَفَكَّهُونَ','اگر ہم چاہیں تو اسے چورا چورا کردیں اور تم باتیں بناتے رہ جاؤ','If We willed, We could simply reduce this ˹harvest˺ to chaff, leaving you to lament','तो उसे चूर चूर कर देते तो तुम बातें ही बनाते रह जाते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,66,'Al-Waaqia','إِنَّا لَمُغۡرَمُونَ','(کہ ہائے) ہم تو مفت تاوان میں پھنس گئے','“We have truly suffered a ˹great˺ loss','कि (हाए) हम तो (मुफ्त) तावान में फॅसे (नहीं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,67,'Al-Waaqia','بَلۡ نَحۡنُ مَحۡرُومُونَ','بلکہ ہم ہیں ہی بےنصیب','In fact, we have been deprived ˹of our livelihood˺.”','हम तो बदनसीब हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,68,'Al-Waaqia','أَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ','بھلا دیکھو تو کہ جو پانی تم پیتے ہو','Have you considered the water you drink','तो क्या तुमने पानी पर भी नज़र डाली जो (दिन रात) पीते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,69,'Al-Waaqia','ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ','کیا تم نے اس کو بادل سے نازل کیا ہے یا ہم نازل کرتے ہیں؟','Is it you who bring it down from the clouds, or is it We Who do so','क्या उसको बादल से तुमने बरसाया है या हम बरसाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,70,'Al-Waaqia','لَوۡ نَشَآءُ جَعَلۡنَٰهُ أُجَاجࣰ ا فَلَوۡلَا تَشۡكُرُونَ','اگر ہم چاہیں تو ہم اسے کھاری کردیں پھر تم شکر کیوں نہیں کرتے؟','If We willed, We could make it salty. Will you not then give thanks','अगर हम चाहें तो उसे खारी बना दें तो तुम लोग यक्र क्यों नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,71,'Al-Waaqia','أَفَرَءَيۡتُمُ ٱلنَّارَ ٱلَّتِي تُورُونَ','بھلا دیکھو تو جو آگ تم درخت سے نکالتے ہو','Have you considered the fire you kindle','तो क्या तुमने आग पर भी ग़ौर किया जिसे तुम लोग लकड़ी से निकालते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,72,'Al-Waaqia','ءَأَنتُمۡ أَنشَأۡتُمۡ شَجَرَتَهَآ أَمۡ نَحۡنُ ٱلۡمُنشِـُٔونَ','کیا تم نے اس کے درخت کو پیدا کیا ہے یا ہم پیدا کرتے ہیں؟','Is it you who produce its trees, or is it We Who do so','क्या उसके दरख्त को तुमने पैदा किया या हम पैदा करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,73,'Al-Waaqia','نَحۡنُ جَعَلۡنَٰهَا تَذۡكِرَةࣰ وَمَتَٰعࣰ ا لِّلۡمُقۡوِينَ','ہم نے اسے یاد دلانے اور مسافروں کے برتنے کو بنایا ہے','We have made it ˹as˺ a reminder ˹of the Hellfire˺ and a provision for the travellers','हमने आग को (जहन्नुम की) याद देहानी और मुसाफिरों के नफे के (वास्ते पैदा किया)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,74,'Al-Waaqia','فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ','تو تم اپنے پروردگار بزرگ کے نام کی تسبیح کرو','So glorify the Name of your Lord, the Greatest','तो (ऐ रसूल) तुम अपने बुज़ुर्ग परवरदिगार की तस्बीह करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,75,'Al-Waaqia','۞فَلَآ أُقۡسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ','ہمیں تاروں کی منزلوں کی قسم','So I do swear by the positions of the stars—','तो मैं तारों के मनाज़िल की क़सम खाता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,76,'Al-Waaqia','وَإِنَّهُۥ لَقَسَمࣱ لَّوۡ تَعۡلَمُونَ عَظِيمٌ','اور اگر تم سمجھو تو یہ بڑی قسم ہے','and this, if only you knew, is indeed a great oath—','और अगर तुम समझो तो ये बड़ी क़सम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,77,'Al-Waaqia','إِنَّهُۥ لَقُرۡءَانࣱ كَرِيمࣱ‏','کہ یہ بڑے رتبے کا قرآن ہے','that this is truly a noble Quran','कि बेशक ये बड़े रूतबे का क़ुरान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,78,'Al-Waaqia','فِي كِتَٰبࣲ مَّكۡنُونࣲ‏','(جو) کتاب محفوظ میں (لکھا ہوا ہے)','in a well-preserved Record','जो किताब (लौहे महफूज़) में (लिखा हुआ) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,79,'Al-Waaqia','لَّا يَمَسُّهُۥٓ إِلَّا ٱلۡمُطَهَّرُونَ','اس کو وہی ہاتھ لگاتے ہیں جو پاک ہیں','touched by none except the purified ˹angels˺','इसको बस वही लोग छूते हैं जो पाक हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,80,'Al-Waaqia','تَنزِيلࣱ مِّن رَّبِّ ٱلۡعَٰلَمِينَ','پروردگار عالم کی طرف سے اُتارا گیا ہے','˹It is˺ a revelation from the Lord of all worlds','सारे जहाँ के परवरदिगार की तरफ से (मोहम्मद पर) नाज़िल हुआ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,81,'Al-Waaqia','أَفَبِهَٰذَا ٱلۡحَدِيثِ أَنتُم مُّدۡهِنُونَ','کیا تم اس کلام سے انکار کرتے ہو؟','How can you then take this message lightly','तो क्या तुम लोग इस कलाम से इन्कार रखते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,82,'Al-Waaqia','وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ','اور اپنا وظیفہ یہ بناتے ہو کہ (اسے) جھٹلاتے ہو','and repay ˹Allah for˺ your provisions with denial','और तुमने अपनी रोज़ी ये करार दे ली है कि (उसको) झुठलाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,83,'Al-Waaqia','فَلَوۡلَآ إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ','بھلا جب روح گلے میں آ پہنچتی ہے','Why then ˹are you helpless˺ when the soul ˹of a dying person˺ reaches ˹their˺ throat','तो क्या जब जान गले तक पहुँचती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,84,'Al-Waaqia','وَأَنتُمۡ حِينَئِذࣲ تَنظُرُونَ','اور تم اس وقت کی (حالت کو) دیکھا کرتے ہو','while you are looking on','और तुम उस वक्त (क़ी हालत) पड़े देखा करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,85,'Al-Waaqia','وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنكُمۡ وَلَٰكِن لَّا تُبۡصِرُونَ','اور ہم اس (مرنے والے) سے تم سے بھی زیادہ نزدیک ہوتے ہیں لیکن تم کو نظر نہیں آتے','And We are nearer to such a person than you, but you cannot see','और हम इस (मरने वाले) से तुमसे भी ज्यादा नज़दीक होते हैं लेकिन तुमको दिखाई नहीं देता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,86,'Al-Waaqia','فَلَوۡلَآ إِن كُنتُمۡ غَيۡرَ مَدِينِينَ','پس اگر تم کسی کے بس میں نہیں ہو','Now, if you are not subject to Our Will ˹as you claim˺','तो अगर तुम किसी के दबाव में नहीं हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,87,'Al-Waaqia','تَرۡجِعُونَهَآ إِن كُنتُمۡ صَٰدِقِينَ','تو اگر سچے ہو تو روح کو پھیر کیوں نہیں لیتے؟','bring that soul back, if what you say is true','तो अगर (अपने दावे में) तुम सच्चे हो तो रूह को फेर क्यों नहीं देते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,88,'Al-Waaqia','فَأَمَّآ إِن كَانَ مِنَ ٱلۡمُقَرَّبِينَ','پھر اگر وہ (خدا کے) مقربوں میں سے ہے','So, if the deceased is one of those brought near ˹to Us˺','पस अगर वह (मरने वाला ख़ुदा के) मुक़र्रेबीन से है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,89,'Al-Waaqia','فَرَوۡحࣱ وَرَيۡحَانࣱ وَجَنَّتُ نَعِيمࣲ‏','تو (اس کے لئے) آرام اور خوشبودار پھول اور نعمت کے باغ ہیں','then ˹such a person will have˺ serenity, fragrance, and a Garden of Bliss','तो (उस के लिए) आराम व आसाइश है और ख़ुशबूदार फूल और नेअमत के बाग़');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,90,'Al-Waaqia','وَأَمَّآ إِن كَانَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ','اور اگر وہ دائیں ہاتھ والوں میں سے ہے','And if the deceased is one of the people of the right','और अगर वह दाहिने हाथ वालों में से है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,91,'Al-Waaqia','فَسَلَٰمࣱ لَّكَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ','تو (کہا جائے گا کہ) تجھ پر داہنے ہاتھ والوں کی طرف سے سلام','then ˹they will be told,˺ “Greetings to you from the people of the right.”','तो (उससे कहा जाएगा कि) तुम पर दाहिने हाथ वालों की तरफ़ से सलाम हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,92,'Al-Waaqia','وَأَمَّآ إِن كَانَ مِنَ ٱلۡمُكَذِّبِينَ ٱلضَّآلِّينَ','اور اگر وہ جھٹلانے والے گمراہوں میں سے ہے','But if such person is one of the misguided deniers','और अगर झुठलाने वाले गुमराहों में से है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,93,'Al-Waaqia','فَنُزُلࣱ مِّنۡ حَمِيمࣲ‏','تو (اس کے لئے) کھولتے پانی کی ضیافت ہے','then their accommodation will be boiling water ˹to drink˺','तो (उसकी) मेहमानी खौलता हुआ पानी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,94,'Al-Waaqia','وَتَصۡلِيَةُ جَحِيمٍ','اور جہنم میں داخل کیا جانا','and burning in Hellfire','और जहन्नुम में दाखिल कर देना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,95,'Al-Waaqia','إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلۡيَقِينِ','یہ (داخل کیا جانا یقیناً صحیح یعنی) حق الیقین ہے','Indeed, this is the absolute truth','बेशक ये (ख़बर) यक़ीनन सही है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (56,96,'Al-Waaqia','فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ','تو تم اپنے پروردگار بزرگ کے نام کی تسبیح کرتے رہو','So glorify the Name of your Lord, the Greatest','तो (ऐ रसूल) तुम अपने बुज़ुर्ग परवरदिगार की तस्बीह करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,1,'Al-Hadid','سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','جو مخلوق آسمانوں اور زمین میں ہے خدا کی تسبیح کرتی ہے۔ اور وہ غالب (اور) حکمت والا ہے','Whatever is in the heavens and the earth glorifies Allah, for He is the Almighty, All-Wise','जो जो चीज़ सारे आसमान व ज़मीन में है सब ख़ुदा की तसबीह करती है और वही ग़ालिब हिकमत वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,2,'Al-Hadid','لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ','آسمانوں اور زمین کی بادشاہی اسی کی ہے۔ (وہی) زندہ کرتا اور مارتا ہے۔ اور وہ ہر چیز پر قادر ہے','To Him belongs the kingdom of the heavens and the earth. He gives life and causes death. And He is Most Capable of everything','सारे आसमान व ज़मीन की बादशाही उसी की है वही जिलाता है वही मारता है और वही हर चीज़ पर कादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,3,'Al-Hadid','هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ','وہ (سب سے) پہلا اور (سب سے) پچھلا اور (اپنی قدرتوں سے سب پر) ظاہر اور (اپنی ذات سے) پوشیدہ ہے اور وہ تمام چیزوں کو جانتا ہے','He is the First and the Last, the Most High and Most Near, and He has ˹perfect˺ knowledge of all things','वही सबसे पहले और सबसे आख़िर है और (अपनी क़ूवतों से) सब पर ज़ाहिर और (निगाहों से) पोशीदा है और वही सब चीज़ों को जानता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,4,'Al-Hadid','هُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۖ وَهُوَ مَعَكُمۡ أَيۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرࣱ‏','وہی ہے جس نے آسمانوں اور زمین کو چھ دن میں پیدا کیا پھر عرش پر جا ٹھہرا۔ جو چیز زمین میں داخل ہوتی اور جو اس سے نکلتی ہے اور جو آسمان سے اُترتی اور جو اس کی طرف چڑھتی ہے سب اس کو معلوم ہے۔ اور تم جہاں کہیں ہو وہ تمہارے ساتھ ہے۔ اور جو کچھ تم کرتے ہو خدا اس کو دیکھ رہا ہے','He is the One Who created the heavens and the earth in six Days, then established Himself on the Throne. He knows whatever goes into the earth and whatever comes out of it, and whatever descends from the sky and whatever ascends into it. And He is with you wherever you are. For Allah is All-Seeing of what you do','वह वही तो है जिसने सारे आसमान व ज़मीन को छह: दिन में पैदा किए फिर अर्श (के बनाने) पर आमादा हुआ जो चीज़ ज़मीन में दाखिल होती है और जो उससे निकलती है और जो चीज़ आसमान से नाज़िल होती है और जो उसकी तरफ चढ़ती है (सब) उसको मालूम है और तुम (चाहे) जहाँ कहीं रहो वह तुम्हारे साथ है और जो कुछ भी तुम करते हो ख़ुदा उसे देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,5,'Al-Hadid','لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','آسمانوں اور زمین کی بادشاہی اسی کی ہے۔ اور سب امور اسی کی طرف رجوع ہوتے ہیں','To Him belongs the kingdom of the heavens and the earth. And to Allah all matters are returned','सारे आसमान व ज़मीन की बादशाही ख़ास उसी की है और ख़ुदा ही की तरफ कुल उमूर की रूजू होती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,6,'Al-Hadid','يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۚ وَهُوَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','رات کو دن میں داخل کرتا اور دن کو رات میں داخل کرتا ہے۔ اور وہ دلوں کے بھیدوں تک سے واقف ہے','He merges the night into day and the day into night. And He knows best what is ˹hidden˺ in the heart','वही रात को (घटा कर) दिन में दाखिल करता है तो दिन बढ़ जाता है और दिन को (घटाकर) रात में दाख़िल करता है (तो रात बढ़ जाती है) और दिलों के भेदों तक से ख़ूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,7,'Al-Hadid','ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرࣱ كَبِيرࣱ‏','(تو) خدا پر اور اس کے رسول پر ایمان لاؤ اور جس (مال) میں اس نے تم کو (اپنا) نائب بنایا ہے اس میں سے خرچ کرو۔ جو لوگ تم میں سے ایمان لائے اور (مال) خرچ کرتے رہے ان کے لئے بڑا ثواب ہے','Believe in Allah and His Messenger, and donate from what He has entrusted you with. So those of you who believe and donate will have a mighty reward','(लोगों) ख़ुदा और उसके रसूल पर ईमान लाओ और जिस (माल) में उसने तुमको अपना नायब बनाया है उसमें से से कुछ (ख़ुदा की राह में) ख़र्च करो तो तुम में से जो लोग ईमान लाए और (राहे ख़ुदा में) ख़र्च करते रहें उनके लिए बड़ा अज्र है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,8,'Al-Hadid','وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدۡعُوكُمۡ لِتُؤۡمِنُواْ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِيثَٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِينَ','اور تم کیسے لوگ ہو کہ خدا پر ایمان نہیں لاتے۔ حالانکہ (اس کے) پیغمبر تمہیں بلا رہے ہیں کہ اپنے پروردگار پر ایمان لاؤ اور اگر تم کو باور ہو تو وہ تم سے (اس کا) عہد بھی لے چکا ہے','Why do you not believe in Allah while the Messenger is inviting you to have faith in your Lord, although He has already taken your covenant, if you will ever believe','और तुम्हें क्या हो गया है कि ख़ुदा पर ईमान नहीं लाते हो हालॉकि रसूल तुम्हें बुला रहें हैं कि अपने परवरदिगार पर ईमान लाओ और अगर तुमको बावर हो तो (यक़ीन करो कि) ख़ुदा तुम से (इसका) इक़रार ले चुका');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,9,'Al-Hadid','هُوَ ٱلَّذِي يُنَزِّلُ عَلَىٰ عَبۡدِهِۦٓ ءَايَٰتِۭ بَيِّنَٰتࣲ لِّيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفࣱ رَّحِيمࣱ‏','وہی تو ہے جو اپنے بندے پر واضح (المطالب) آیتیں نازل کرتا ہے تاکہ تم کو اندھیروں میں سے نکال کر روشنی میں لائے۔ بےشک خدا تم پر نہایت شفقت کرنے والا (اور) مہربان ہے','He is the One Who sends down clear revelations to His servant to bring you out of darkness and into light. For indeed Allah is Ever Gracious and Most Merciful to you','वही तो है जो अपने बन्दे (मोहम्मद) पर वाज़ेए व रौशन आयतें नाज़िल करता है ताकि तुम लोगों को (कुफ़्र की) तारिक़ीयों से निकाल कर (ईमान की) रौशनी में ले जाए और बेशक ख़ुदा तुम पर बड़ा मेहरबान और निहायत रहम वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,10,'Al-Hadid','وَمَا لَكُمۡ أَلَّا تُنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا يَسۡتَوِي مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَٰتَلَۚ أُوْلَٰٓئِكَ أَعۡظَمُ دَرَجَةࣰ مِّنَ ٱلَّذِينَ أَنفَقُواْ مِنۢ بَعۡدُ وَقَٰتَلُواْۚ وَكُلࣰّ ا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ‏','اور تم کو کیا ہوا ہے کہ خدا کے رستے میں خرچ نہیں کرتے حالانکہ آسمانوں اور زمین کی وراثت خدا ہی کی ہے۔ جس شخص نے تم میں سے فتح (مکہ) سے پہلے خرچ کیا اور لڑائی کی وہ (اور جس نے یہ کام پیچھے کئے وہ) برابر نہیں۔ ان کا درجہ ان لوگوں سے کہیں بڑھ کر ہے جنہوں نے بعد میں خرچ (اموال) اور (کفار سے) جہاد وقتال کیا۔ اور خدا نے سب سے (ثواب) نیک (کا) وعدہ تو کیا ہے۔ اور جو کام تم کرتے ہو خدا ان سے واقف ہے','And why should you not spend in the cause of Allah, while Allah is the ˹sole˺ inheritor of the heavens and the earth? Those of you who donated and fought before the victory ˹over Mecca˺ are unparalleled. They are far greater in rank than those who donated and fought afterwards. Yet Allah has promised each a fine reward. And Allah is All-Aware of what you do','और तुमको क्या हो गया कि (अपना माल) ख़ुदा की राह में ख़र्च नहीं करते हालॉकि सारे आसमान व ज़मीन का मालिक व वारिस ख़ुदा ही है तुममें से जिस शख़्श ने फतेह (मक्का) से पहले (अपना माल) ख़र्च किया और जेहाद किया (और जिसने बाद में किया) वह बराबर नहीं उनका दर्जा उन लोगों से कहीं बढ़ कर है जिन्होंने बाद में ख़र्च किया और जेहाद किया और (यूँ तो) ख़ुदा ने नेकी और सवाब का वायदा तो सबसे किया है और जो कुछ तुम करते हो ख़ुदा उससे ख़ूब वाक़िफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,11,'Al-Hadid','مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰ ا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرࣱ كَرِيمࣱ‏','کون ہے جو خدا کو (نیت) نیک (اور خلوص سے) قرض دے تو وہ اس کو اس سے دگنا کرے اور اس کے لئے عزت کا صلہ (یعنی جنت) ہے','Who is it that will lend to Allah a good loan which Allah will multiply ˹many times over˺ for them, and they will have an honourable reward','कौन ऐसा है जो ख़ुदा को ख़ालिस नियत से कर्जे हसना दे तो ख़ुदा उसके लिए (अज्र को) दूना कर दे और उसके लिए बहुत मुअज्ज़िज़ सिला (जन्नत) तो है ही');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,12,'Al-Hadid','يَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡيَوۡمَ جَنَّٰتࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ','جس دن تم مومن مردوں اور مومن عورتوں کو دیکھو گے کہ ان (کے ایمان) کا نور ان کے آگے آگے اور داہنی طرف چل رہا ہے (تو ان سے کہا جائے گا کہ) تم کو بشارت ہو (کہ آج تمہارے لئے) باغ ہیں جن کے تلے نہریں بہہ رہی ہیں ان میں ہمیشہ رہو گے۔ یہی بڑی کامیابی ہے','On that Day you will see believing men and women with their light shining ahead of them and on their right. ˹They will be told,˺ “Today you have good news of Gardens, under which rivers flow, ˹for you˺ to stay in forever. This is ˹truly˺ the ultimate triumph.”','जिस दिन तुम मोमिन मर्द और मोमिन औरतों को देखोगे कि उन (के ईमान) का नूर उनके आगे आगे और दाहिने तरफ चल रहा होगा तो उनसे कहा (जाएगा) तुमको बशारत हो कि आज तुम्हारे लिए वह बाग़ है जिनके नीचे नहरें जारी हैं जिनमें हमेशा रहोगे यही तो बड़ी कामयाबी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,13,'Al-Hadid','يَوۡمَ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُواْ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِيلَ ٱرۡجِعُواْ وَرَآءَكُمۡ فَٱلۡتَمِسُواْ نُورࣰ اۖ فَضُرِبَ بَيۡنَهُم بِسُورࣲ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِيهِ ٱلرَّحۡمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ','اُس دن منافق مرد اور منافق عورتیں مومنوں سے کہیں گے کہ ہماری طرف سے (شفقت) کیجیئے کہ ہم بھی تمہارے نور سے روشنی حاصل کریں۔ تو ان سے کہا جائے گا کہ پیچھے کو لوٹ جاؤ اور (وہاں) نور تلاش کرو۔ پھر ان کے بیچ میں ایک دیوار کھڑی کر دی جائے گی۔ جس میں ایک دروازہ ہوگا جو اس کی جانب اندرونی ہے اس میں تو رحمت ہے اور جو جانب بیرونی ہے اس طرف عذاب (واذیت)','On that Day hypocrite men and women will beg the believers, “Wait for us so that we may have some of your light.” It will be said ˹mockingly˺, “Go back ˹to the world˺ and seek a light ˹there˺!” Then a ˹separating˺ wall with a gate will be erected between them. On the near side will be grace and on the far side will be torment','उस दिन मुनाफ़िक मर्द और मुनाफ़िक औरतें ईमानदारों से कहेंगे एक नज़र (शफ़क्क़त) हमारी तरफ़ भी करो कि हम भी तुम्हारे नूर से कुछ रौशनी हासिल करें तो (उनसे) कहा जाएगा कि तुम अपने पीछे (दुनिया में) लौट जाओ और (वही) किसी और नूर की तलाश करो फिर उनके बीच में एक दीवार खड़ी कर दी जाएगी जिसमें एक दरवाज़ा होगा (और) उसके अन्दर की जानिब तो रहमत है और बाहर की तरफ अज़ाब तो मुनाफ़िक़ीन मोमिनीन से पुकार कर कहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,14,'Al-Hadid','يُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُواْ بَلَىٰ وَلَٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِيُّ حَتَّىٰ جَآءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ','تو منافق لوگ مومنوں سے کہیں گے کہ کیا ہم (دنیا میں) تمہارے ساتھ نہ تھے وہ کہیں گے کیوں نہیں تھے۔ لیکن تم نے خود اپنے تئیں بلا میں ڈالا اور (ہمارے حق میں حوادث کے) منتظر رہے اور (اسلام میں) شک کیا اور (لاطائل) آرزوؤں نے تم کو دھوکہ دیا یہاں تک کہ خدا کا حکم آ پہنچا اور خدا کے بارے میں تم کو (شیطان) دغاباز دغا دیتا رہا','The tormented will cry out to those graced, “Were we not with you?” They will reply, “Yes ˹you were˺. But you chose to be tempted ˹by hypocrisy˺, ˹eagerly˺ awaited ˹our demise˺, doubted ˹the truth˺, and were deluded by false hopes until Allah’s decree ˹of your death˺ came to pass. And ˹so˺ the Chief Deceiver deceived you about Allah','(क्यों भाई) क्या हम कभी तुम्हारे साथ न थे तो मोमिनीन कहेंगे थे तो ज़रूर मगर तुम ने तो ख़ुद अपने आपको बला में डाला और (हमारे हक़ में गर्दिशों के) मुन्तज़िर हैं और (दीन में) शक़ किया किए और तुम्हें (तुम्हारी) तमन्नाओं ने धोखे में रखा यहाँ तक कि ख़ुदा का हुक्म आ पहुँचा और एक बड़े दग़ाबाज़ (शैतान) ने ख़ुदा के बारे में तुमको फ़रेब दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,15,'Al-Hadid','فَٱلۡيَوۡمَ لَا يُؤۡخَذُ مِنكُمۡ فِدۡيَةࣱ وَلَا مِنَ ٱلَّذِينَ كَفَرُواْۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِيَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِيرُ','تو آج تم سے معاوضہ نہیں لیا جائے گا اور نہ (وہ) کافروں ہی سے (قبول کیا جائے گا) تم سب کا ٹھکانا دوزخ ہے۔ (کہ) وہی تمہارے لائق ہے اور وہ بری جگہ ہے','So Today no ransom will be accepted from you ˹hypocrites˺, nor from the disbelievers. Your home is the Fire—it is the ˹only˺ fitting place for you. What an evil destination!”','तो आज न तो तुमसे कोई मुआवज़ा लिया जाएगा और न काफ़िरों से तुम सबका ठिकाना (बस) जहन्नुम है वही तुम्हारे वास्ते सज़ावार है और (क्या) बुरी जगह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,16,'Al-Hadid','۞أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرࣱ مِّنۡهُمۡ فَٰسِقُونَ','کیا ابھی تک مومنوں کے لئے اس کا وقت نہیں آیا کہ خدا کی یاد کرنے کے وقت اور (قرآن) جو (خدائے) برحق (کی طرف) سے نازل ہوا ہے اس کے سننے کے وقت ان کے دل نرم ہوجائیں اور وہ ان لوگوں کی طرف نہ ہوجائیں جن کو (ان سے) پہلے کتابیں دی گئی تھیں۔ پھر ان پر زمان طویل گزر گیا تو ان کے دل سخت ہوگئے۔ اور ان میں سے اکثر نافرمان ہیں','Has the time not yet come for believers’ hearts to be humbled at the remembrance of Allah and what has been revealed of the truth, and not be like those given the Scripture before—˹those˺ who were spoiled for so long that their hearts became hardened. And many of them are ˹still˺ rebellious','क्या ईमानदारों के लिए अभी तक इसका वक्त नहीं आया कि ख़ुदा की याद और क़ुरान के लिए जो (ख़ुदा की तरफ से) नाज़िल हुआ है उनके दिल नरम हों और वह उन लोगों के से न हो जाएँ जिनको उन से पहले किताब (तौरेत, इन्जील) दी गयी थी तो (जब) एक ज़माना दराज़ गुज़र गया तो उनके दिल सख्त हो गए और इनमें से बहुतेरे बदकार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,17,'Al-Hadid','ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ','جان رکھو کہ خدا ہی زمین کو اس کے مرنے کے بعد زندہ کرتا ہے۔ ہم نے اپنی نشانیاں تم سے کھول کھول کر بیان کردی ہیں تاکہ تم سمجھو','Know that Allah revives the earth after its death. We have certainly made the signs clear for you so perhaps you will understand','जान रखो कि ख़ुदा ही ज़मीन को उसके मरने (उफ़तादा होने) के बाद ज़िन्दा (आबाद) करता है हमने तुमसे अपनी (क़ुदरत की) निशानियाँ खोल खोल कर बयान कर दी हैं ताकि तुम समझो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,18,'Al-Hadid','إِنَّ ٱلۡمُصَّدِّقِينَ وَٱلۡمُصَّدِّقَٰتِ وَأَقۡرَضُواْ ٱللَّهَ قَرۡضًا حَسَنࣰ ا يُضَٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرࣱ كَرِيمࣱ‏','جو لوگ خیرات کرنے والے ہیں مرد بھی اور عورتیں بھی۔ اور خدا کو (نیت) نیک (اور خلوص سے) قرض دیتے ہیں ان کو دوچند ادا کیا جائے گا اور ان کے لئے عزت کا صلہ ہے','Indeed, those men and women who give in charity and lend to Allah a good loan will have it multiplied for them, and they will have an honourable reward','बेशक ख़ैरात देने वाले मर्द और ख़ैरात देने वाली औरतें और (जो लोग) ख़ुदा की नीयत से ख़ालिस कर्ज़ देते हैं उनको दोगुना (अज्र) दिया जाएगा और उनका बहुत मुअज़िज़ सिला (जन्नत) तो है ही');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,19,'Al-Hadid','وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ','اور جو لوگ خدا اور اس کے پیغمبروں پر ایمان لائے یہی اپنے پروردگار کے نزدیک صدیق اور شہید ہیں۔ ان کے لئے ان (کے اعمال) کا صلہ ہوگا۔ اور ان (کے ایمان) کی روشنی۔ اور جن لوگوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہی اہل دوزخ ہیں','˹As for˺ those who believe in Allah and His messengers, it is they who are ˹truly˺ the people of truth. And the martyrs, with their Lord, will have their reward and their light. But ˹as for˺ those who disbelieve and reject Our signs, it is they who will be the residents of the Hellfire','और जो लोग ख़ुदा और उसके रसूलों पर ईमान लाए यही लोग अपने परवरदिगार के नज़दीक सिद्दीक़ों और शहीदों के दरजे में होंगे उनके लिए उन्ही (सिद्दीकों और शहीदों) का अज्र और उन्हीं का नूर होगा और जिन लोगों ने कुफ्र किया और हमारी आयतों को झुठलाया वही लोग जहन्नुमी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,20,'Al-Hadid','ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبࣱ وَلَهۡوࣱ وَزِينَةࣱ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرࣱ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِۖ كَمَثَلِ غَيۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرࣰّ ا ثُمَّ يَكُونُ حُطَٰمࣰ اۖ وَفِي ٱلۡأٓخِرَةِ عَذَابࣱ شَدِيدࣱ وَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرِضۡوَٰنࣱۚ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ','جان رکھو کہ دنیا کی زندگی محض کھیل اور تماشا اور زینت (وآرائش) اور تمہارے آپس میں فخر (وستائش) اور مال واولاد کی ایک دوسرے سے زیادہ طلب (وخواہش) ہے (اس کی مثال ایسی ہے) جیسے بارش کہ (اس سے کھیتی اُگتی اور) کسانوں کو کھیتی بھلی لگتی ہے پھر وہ خوب زور پر آتی ہے پھر (اے دیکھنے والے) تو اس کو دیکھتا ہے کہ (پک کر) زرد پڑ جاتی ہے پھر چورا چورا ہوجاتی ہے اور آخرت میں (کافروں کے لئے) عذاب شدید اور (مومنوں کے لئے) خدا کی طرف سے بخشش اور خوشنودی ہے۔ اور دنیا کی زندگی تو متاع فریب ہے','Know that this worldly life is no more than play, amusement, luxury, mutual boasting, and competition in wealth and children. This is like rain that causes plants to grow, to the delight of the planters. But later the plants dry up and you see them wither, then they are reduced to chaff. And in the Hereafter there will be either severe punishment or forgiveness and pleasure of Allah, whereas the life of this world is no more than the delusion of enjoyment','जान रखो कि दुनियावी ज़िन्दगी महज़ खेल और तमाशा और ज़ाहिरी ज़ीनत (व आसाइश) और आपस में एक दूसरे पर फ़ख्र क़रना और माल और औलाद की एक दूसरे से ज्यादा ख्वाहिश है (दुनयावी ज़िन्दगी की मिसाल तो) बारिश की सी मिसाल है जिस (की वजह) से किसानों की खेती (लहलहाती और) उनको ख़ुश कर देती थी फिर सूख जाती है तो तू उसको देखता है कि ज़र्द हो जाती है फिर चूर चूर हो जाती है और आख़िरत में (कुफ्फार के लिए) सख्त अज़ाब है और (मोमिनों के लिए) ख़ुदा की तरफ से बख़्शिस और ख़ुशनूदी और दुनयावी ज़िन्दगी तो बस फ़रेब का साज़ो सामान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,21,'Al-Hadid','سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','(بندو) اپنے پروردگار کی بخشش کی طرف اور جنت کی (طرف) جس کا عرض آسمان اور زمین کے عرض کا سا ہے۔ اور جو ان لوگوں کے لئے تیار کی گئی ہے جو خدا پر اور اس کے پیغمبروں پر ایمان لائے ہیں لپکو۔ یہ خدا کا فضل ہے جسے چاہے عطا فرمائے۔ اور خدا بڑے فضل کا مالک ہے','˹So˺ compete with one another for forgiveness from your Lord and a Paradise as vast as the heavens and the earth, prepared for those who believe in Allah and His messengers. This is the favour of Allah. He grants it to whoever He wills. And Allah is the Lord of infinite bounty','तुम अपने परवरदिगार के (सबब) बख़्शिस की और बेहिश्त की तरफ लपक के आगे बढ़ जाओ जिसका अर्ज़ आसमान और ज़मीन के अर्ज़ के बराबर है जो उन लोगों के लिए तैयार की गयी है जो ख़ुदा पर और उसके रसूलों पर ईमान लाए हैं ये ख़ुदा का फज़ल है जिसे चाहे अता करे और ख़ुदा का फज़ल (व क़रम) तो बहुत बड़ा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,22,'Al-Hadid','مَآ أَصَابَ مِن مُّصِيبَةࣲ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبࣲ مِّن قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣱ‏','کوئی مصیبت ملک پر اور خود تم پر نہیں پڑتی مگر پیشتر اس کے کہ ہم اس کو پیدا کریں ایک کتاب میں (لکھی ہوئی) ہے۔ (اور) یہ (کام) خدا کو آسان ہے','No calamity ˹or blessing˺ occurs on earth or in yourselves without being ˹written˺ in a Record before We bring it into being. This is certainly easy for Allah','जितनी मुसीबतें रूए ज़मीन पर और ख़ुद तुम लोगों पर नाज़िल होती हैं (वह सब) क़ब्ल इसके कि हम उन्हें पैदा करें किताब (लौह महफूज़) में (लिखी हुई) हैं बेशक ये ख़ुदा पर आसान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,23,'Al-Hadid','لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورٍ','تاکہ جو (مطلب) تم سے فوت ہوگیا ہو اس کا غم نہ کھایا کرو اور جو تم کو اس نے دیا ہو اس پر اترایا نہ کرو۔ اور خدا کسی اترانے اور شیخی بگھارنے والے کو دوست نہیں رکھتا','˹We let you know this˺ so that you neither grieve over what you have missed nor boast over what He has granted you. For Allah does not like whoever is arrogant, boastful—','ताकि जब कोई चीज़ तुमसे जाती रहे तो तुम उसका रंज न किया करो और जब कोई चीज़ (नेअमत) ख़ुदा तुमको दे तो उस पर न इतराया करो और ख़ुदा किसी इतराने वाले येख़ी बाज़ को दोस्त नहीं रखता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,24,'Al-Hadid','ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','جو خود بھی بخل کریں اور لوگوں کو بھی بخل سکھائیں اور جو شخص روگردانی کرے تو خدا بھی بےپروا (اور) وہی سزاوار حمد (وثنا) ہے','those who are stingy and promote stinginess among people. And whoever turns away ˹should know that˺ Allah ˹alone˺ is truly the Self-Sufficient, Praiseworthy','जो ख़ुद भी बुख्ल करते हैं और दूसरे लोगों को भी बुख्ल करना सिखाते हैं और जो शख़्श (इन बातों से) रूगरदानी करे तो ख़ुदा भी बेपरवा सज़ावारे हम्दोसना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,25,'Al-Hadid','لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسࣱ شَدِيدࣱ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزࣱ‏','ہم نے اپنے پیغمبروں کو کھلی نشانیاں دے کر بھیجا۔ اور اُن پر کتابیں نازل کیں اور ترازو (یعنی قواعد عدل) تاکہ لوگ انصاف پر قائم رہیں۔ اور لوہا پیدا کیا اس میں (اسلحہٴ جنگ کے لحاظ سے) خطرہ بھی شدید ہے۔ اور لوگوں کے لئے فائدے بھی ہیں اور اس لئے کہ جو لوگ بن دیکھے خدا اور اس کے پیغمبروں کی مدد کرتے ہیں خدا ان کو معلوم کرے۔ بےشک خدا قوی (اور) غالب ہے','Indeed, We sent Our messengers with clear proofs, and with them We sent down the Scripture and the balance ˹of justice˺ so that people may administer justice. And We sent down iron with its great might, benefits for humanity, and means for Allah to prove who ˹is willing to˺ stand up for Him and His messengers without seeing Him. Surely Allah is All-Powerful, Almighty','हमने यक़ीनन अपने पैग़म्बरों को वाज़े व रौशन मोजिज़े देकर भेजा और उनके साथ किताब और (इन्साफ़ की) तराज़ू नाज़िल किया ताकि लोग इन्साफ़ पर क़ायम रहे और हम ही ने लोहे को नाज़िल किया जिसके ज़रिए से सख्त लड़ाई और लोगों के बहुत से नफे (की बातें) हैं और ताकि ख़ुदा देख ले कि बेदेखे भाले ख़ुदा और उसके रसूलों की कौन मदद करता है बेशक ख़ुदा बहुत ज़बरदस्त ग़ालिब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,26,'Al-Hadid','وَلَقَدۡ أَرۡسَلۡنَا نُوحࣰ ا وَإِبۡرَٰهِيمَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَۖ فَمِنۡهُم مُّهۡتَدࣲۖ وَكَثِيرࣱ مِّنۡهُمۡ فَٰسِقُونَ','اور ہم نے نوح اور ابراہیم کو (پیغمبر بنا کر) بھیجا اور ان کی اولاد میں پیغمبری اور کتاب (کے سلسلے) کو (وقتاً فوقتاً جاری) رکھا تو بعض تو ان میں سے ہدایت پر ہیں۔ اور اکثر ان میں سے خارج از اطاعت ہیں','And indeed, We sent Noah and Abraham and reserved prophethood and revelation for their descendants. Some of them are ˹rightly˺ guided, while most are rebellious','और बेशक हम ही ने नूह और इबराहीम को (पैग़म्बर बनाकर) भेजा और उनही दोनों की औलाद में नबूवत और किताब मुक़र्रर की तो उनमें के बाज़ हिदायत याफ्ता हैं और उन के बहुतेरे बदकार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,27,'Al-Hadid','ثُمَّ قَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى ٱبۡنِ مَرۡيَمَ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَۖ وَجَعَلۡنَا فِي قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأۡفَةࣰ وَرَحۡمَةࣰۚ وَرَهۡبَانِيَّةً ٱبۡتَدَعُوهَا مَا كَتَبۡنَٰهَا عَلَيۡهِمۡ إِلَّا ٱبۡتِغَآءَ رِضۡوَٰنِ ٱللَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَايَتِهَاۖ فَـَٔاتَيۡنَا ٱلَّذِينَ ءَامَنُواْ مِنۡهُمۡ أَجۡرَهُمۡۖ وَكَثِيرࣱ مِّنۡهُمۡ فَٰسِقُونَ','پھر ان کے پیچھے انہی کے قدموں پر (اور) پیغمبر بھیجے اور ان کے پیچھے مریمؑ کے بیٹے عیسیٰ کو بھیجا اور ان کو انجیل عنایت کی۔ اور جن لوگوں نے ان کی پیروی کی ان کے دلوں میں شفقت اور مہربانی ڈال دی۔ اور لذات سے کنارہ کشی کی تو انہوں نے خود ایک نئی بات نکال لی ہم نے ان کو اس کا حکم نہیں دیا تھا مگر (انہوں نے اپنے خیال میں) خدا کی خوشنودی حاصل کرنے کے لئے (آپ ہی ایسا کرلیا تھا) پھر جیسا اس کو نباہنا چاہیئے تھا نباہ بھی نہ سکے۔ پس جو لوگ ان میں سے ایمان لائے ان کو ہم نے ان کا اجر دیا اور ان میں بہت سے نافرمان ہیں','Then in the footsteps of these ˹prophets˺, We sent Our messengers, and ˹after them˺ We sent Jesus, son of Mary, and granted him the Gospel, and instilled compassion and mercy into the hearts of his followers. As for monasticism, they made it up—We never ordained it for them—only seeking to please Allah, yet they did not ˹even˺ observe it strictly. So We rewarded those of them who were faithful. But most of them are rebellious','फिर उनके पीछे ही उनके क़दम ब क़दम अपने और पैग़म्बर भेजे और उनके पीछे मरियम के बेटे ईसा को भेजा और उनको इन्जील अता की और जिन लोगों ने उनकी पैरवी की उनके दिलों में यफ़क्क़त और मेहरबानी डाल दी और रहबानियत (लज्ज़ात से किनाराकशी) उन लोगों ने ख़ुद एक नयी बात निकाली थी हमने उनको उसका हुक्म नहीं दिया था मगर (उन लोगों ने) ख़ुदा की ख़ुशनूदी हासिल करने की ग़रज़ से (ख़ुद ईजाद किया) तो उसको भी जैसा बनाना चाहिए था न बना सके तो जो लोग उनमें से ईमान लाए उनको हमने उनका अज्र दिया उनमें के बहुतेरे तो बदकार ही हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,28,'Al-Hadid','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ وَيَجۡعَل لَّكُمۡ نُورࣰ ا تَمۡشُونَ بِهِۦ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِيمࣱ‏','مومنو! خدا سے ڈرو اور اس کے پیغمبر پر ایمان لاؤ وہ تمہیں اپنی رحمت سے دگنا اجر عطا فرمائے گا اور تمہارے لئے روشنی کردے گا جس میں چلو گے اور تم کو بخش دے گا۔ اور خدا بخشنے والا مہربان ہے','O people of faith! Fear Allah and believe in His Messenger. ˹And˺ He will grant you a double share of His mercy, provide you with a light to walk in ˹on Judgment Day˺, and forgive you. For Allah is All-Forgiving, Most Merciful','ऐ ईमानदारों ख़ुदा से डरो और उसके रसूल (मोहम्मद) पर ईमान लाओ तो ख़ुदा तुमको अपनी रहमत के दो हिस्से अज्र अता फरमाएगा और तुमको ऐसा नूर इनायत फ़रमाएगा जिस (की रौशनी) में तुम चलोगे और तुमको बख्श भी देगा और ख़ुदा तो बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (57,29,'Al-Hadid','لِّئَلَّا يَعۡلَمَ أَهۡلُ ٱلۡكِتَٰبِ أَلَّا يَقۡدِرُونَ عَلَىٰ شَيۡءࣲ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','(یہ باتیں) اس لئے (بیان کی گئی ہیں) کہ اہل کتاب جان لیں کہ وہ خدا کے فضل پر کچھ بھی قدرت نہیں رکھتے۔ اور یہ کہ فضل خدا ہی کے ہاتھ ہے جس کو چاہتا ہے دیتا ہے اور خدا بڑے فضل کا مالک ہے','˹This is so˺ that the People of the Book ˹who deny the Prophet˺ may know that they do not have any control over Allah’s grace, and that all grace is in Allah’s Hands. He grants it to whoever He wills. For Allah is the Lord of infinite bounty','(ये इसलिए कहा जाता है) ताकि अहले किताब ये न समझें कि ये मोमिनीन ख़ुदा के फज़ल (व क़रम) पर कुछ भी कुदरत नहीं रखते और ये तो यक़ीनी बात है कि फज़ल ख़ुदा ही के कब्ज़े में है वह जिसको चाहे अता फरमाए और ख़ुदा तो बड़े फज़ल (व क़रम) का मालिक है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,1,'Al-Mujaadila','قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ','(اے پیغمبر) جو عورت تم سے اپنے شوہر کے بارے میں بحث جدال کرتی اور خدا سے شکایت (رنج وملال) کرتی تھی۔ خدا نے اس کی التجا سن لی اور خدا تم دونوں کی گفتگو سن رہا تھا۔ کچھ شک نہیں کہ خدا سنتا دیکھتا ہے','Indeed, Allah has heard the argument of the woman who pleaded with you ˹O Prophet˺ concerning her husband, and appealed to Allah. Allah has heard your exchange. Surely Allah is All-Hearing, All-Seeing','ऐ रसूल जो औरत (ख़ुला) तुमसे अपने शौहर (उस) के बारे में तुमसे झगड़ती और ख़ुदा से गिले शिकवे करती है ख़ुदा ने उसकी बात सुन ली और ख़ुदा तुम दोनों की ग़ुफ्तगू सुन रहा है बेशक ख़ुदा बड़ा सुनने वाला देखने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,2,'Al-Mujaadila','ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرࣰ ا مِّنَ ٱلۡقَوۡلِ وَزُورࣰ اۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ‏','جو لوگ تم میں سے اپنی عورتوں کو ماں کہہ دیتے ہیں وہ ان کی مائیں نہیں (ہوجاتیں) ۔ ان کی مائیں تو وہی ہیں جن کے بطن سے وہ پیدا ہوئے۔ بےشک وہ نامعقول اور جھوٹی بات کہتے ہیں اور خدا بڑا معاف کرنے والا (اور) بخشنے والا ہے','Those of you who ˹sinfully˺ divorce their wives by comparing them to their mothers ˹should know that˺ their wives are in no way their mothers. None can be their mothers except those who gave birth to them. What they say is certainly detestable and false. Yet Allah is truly Ever-Pardoning, All-Forgiving','तुम में से जो लोग अपनी बीवियों के साथ ज़हार करते हैं अपनी बीवी को माँ कहते हैं वह कुछ उनकी माएँ नहीं (हो जातीं) उनकी माएँ तो बस वही हैं जो उनको जनती हैं और वह बेशक एक नामाक़ूल और झूठी बात कहते हैं और ख़ुदा बेशक माफ करने वाला और बड़ा बख्शने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,3,'Al-Mujaadila','وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةࣲ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ‏','اور جو لوگ اپنی بیویوں کو ماں کہہ بیٹھیں پھر اپنے قول سے رجوع کرلیں تو (ان کو) ہم بستر ہونے سے پہلے ایک غلام آزاد کرنا (ضروری) ہے۔ (مومنو) اس (حکم) سے تم کو نصیحت کی جاتی ہے۔ اور جو کچھ تم کرتے ہو خدا اس سے خبردار ہے','Those who divorce their wives in this manner, then ˹wish to˺ retract what they said, must free a slave before they touch each other. This ˹penalty˺ is meant to deter you. And Allah is All-Aware of what you do','और जो लोग अपनी बीवियों से ज़हार कर बैठे फिर अपनी बात वापस लें तो दोनों के हमबिस्तर होने से पहले (कफ्फ़ारे में) एक ग़ुलाम का आज़ाद करना (ज़रूरी) है उसकी तुमको नसीहत की जाती है और तुम जो कुछ भी करते हो (ख़ुदा) उससे आगाह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,4,'Al-Mujaadila','فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينࣰ اۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ','جس کو غلام نہ ملے وہ مجامعت سے پہلے متواتر دو مہینے کے روزے (رکھے) جس کو اس کا بھی مقدور نہ ہوا (اسے) ساٹھ مسکینوں کو کھانا کھلانا (چاہیئے) ۔ یہ (حکم) اس لئے (ہے) کہ تم خدا اور اسکے رسول کے فرمانبردار ہوجاؤ۔ اور یہ خدا کی حدیں ہیں۔ اور نہ ماننے والوں کے لئے درد دینے والا عذاب ہے','But if the husband cannot afford this, let him then fast two consecutive months before the couple touch each other. But if he is unable ˹to fast˺, then let him feed sixty poor people. This is to re-affirm your faith in Allah and His Messenger. These are the limits set by Allah. And the disbelievers will suffer a painful punishment','फिर जिसको ग़ुलाम न मिले तो दोनों की मुक़ारबत के क़ब्ल दो महीने के पै दर पै रोज़े रखें और जिसको इसकी भी क़ुदरत न हो साठ मोहताजों को खाना खिलाना फर्ज़ है ये (हुक्म इसलिए है) ताकि तुम ख़ुदा और उसके रसूल की (पैरवी) तसदीक़ करो और ये ख़ुदा की मुक़र्रर हदें हैं और काफ़िरों के लिए दर्दनाक अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,5,'Al-Mujaadila','إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُواْ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَآ ءَايَٰتِۭ بَيِّنَٰتࣲۚ وَلِلۡكَٰفِرِينَ عَذَابࣱ مُّهِينࣱ‏','جو لوگ خدا اور اس کے رسول کی مخالفت کرتے ہیں وہ (اسی طرح) ذلیل کئے جائیں گے جس طرح ان سے پہلے لوگ ذلیل کئے گئے تھے اور ہم نے صاف اور صریح آیتیں نازل کردی ہیں۔ جو نہیں مانتے ان کو ذلت کا عذاب ہوگا','Indeed, those who defy Allah and His Messenger will be debased, just like those before them. We have certainly sent down clear revelations. And the disbelievers will suffer a humiliating punishment','बेशक जो लोग ख़ुदा की और उसके रसूल की मुख़ालेफ़त करते हैं वह (उसी तरह) ज़लील किए जाएँगे जिस तरह उनके पहले लोग किए जा चुके हैं और हम तो अपनी साफ़ और सरीही आयतें नाज़िल कर चुके और काफिरों के लिए ज़लील करने वाला अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,6,'Al-Mujaadila','يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعࣰ ا فَيُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ','جس دن خدا ان سب کو جلا اٹھائے گا تو جو کام وہ کرتے رہے ان کو جتائے گا۔ خدا کو وہ سب (کام) یاد ہیں اور یہ ان کو بھول گئے ہیں اور خدا ہر چیز سے واقف ہے','On the Day Allah resurrects them all together, He will then inform them of what they have done. Allah has kept account of it all, while they have forgotten it. For Allah is a Witness over all things','जिस दिन ख़ुदा उन सबको दोबारा उठाएगा तो उनके आमाल से उनको आगाह कर देगा ये लोग (अगरचे) उनको भूल गये हैं मगर ख़ुदा ने उनको याद रखा है और ख़ुदा तो हर चीज़ का गवाह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,7,'Al-Mujaadila','أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ مَا يَكُونُ مِن نَّجۡوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَآ أَدۡنَىٰ مِن ذَٰلِكَ وَلَآ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُواْۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُواْ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ','کیا تم کو معلوم نہیں کہ جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے خدا کو سب معلوم ہے۔ (کسی جگہ) تین (شخصوں) کا (مجمع اور) کانوں میں صلاح ومشورہ نہیں ہوتا مگر وہ ان میں چوتھا ہوتا ہے اور نہ کہیں پانچ کا مگر وہ ان میں چھٹا ہوتا ہے اور نہ اس سے کم یا زیادہ مگر وہ ان کے ساتھ ہوتا ہے خواہ وہ کہیں ہوں۔ پھر جو جو کام یہ کرتے رہے ہیں قیامت کے دن وہ (ایک ایک) ان کو بتائے گا۔ بےشک خدا ہر چیز سے واقف ہے','Do you not see that Allah knows whatever is in the heavens and whatever is on the earth? If three converse privately, He is their fourth. If five, He is their sixth. Whether fewer or more, He is with them wherever they may be. Then, on the Day of Judgment, He will inform them of what they have done. Surely Allah has ˹perfect˺ knowledge of all things','क्या तुमको मालूम नहीं कि जो कुछ आसमानों में है और जो कुछ ज़मीन में है (ग़रज़ सब कुछ) ख़ुदा जानता है जब तीन (आदमियों) का ख़ुफिया मशवेरा होता है तो वह (ख़ुद) उनका ज़रूर चौथा है और जब पाँच का मशवेरा होता है तो वह उनका छठा है और उससे कम हो या ज्यादा और चाहे जहाँ कहीं हो वह उनके साथ ज़रूर होता है फिर जो कुछ वह (दुनिया में) करते रहे क़यामत के दिन उनको उससे आगाह कर देगा बेशक ख़ुदा हर चीज़ से ख़ूब वाक़िफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,8,'Al-Mujaadila','أَلَمۡ تَرَ إِلَى ٱلَّذِينَ نُهُواْ عَنِ ٱلنَّجۡوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُواْ عَنۡهُ وَيَتَنَٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِۖ وَإِذَا جَآءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ لَوۡلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ يَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِيرُ','کیا تم نے ان لوگوں کو نہیں دیکھا جن کو سرگوشیاں کرنے سے منع کیا گیا تھا۔ پھر جس (کام) سے منع کیا گیا تھا وہی پھر کرنے لگے اور یہ تو گناہ اور ظلم اور رسول (خدا) کی نافرمانی کی سرگوشیاں کرتے ہیں۔ اور جب تمہارے پاس آتے ہیں تو جس (کلمے) سے خدا نے تم کو دعا نہیں دی اس سے تمہیں دعا دیتے ہیں۔ اور اپنے دل میں کہتے ہیں کہ (اگر یہ واقعی پیغمبر ہیں تو) جو کچھ ہم کہتے ہیں خدا ہمیں اس کی سزا کیوں نہیں دیتا؟ (اے پیغمبر) ان کو دوزخ (ہی کی سزا) کافی ہے۔ یہ اسی میں داخل ہوں گے۔ اور وہ بری جگہ ہے','Have you not seen those who were forbidden from secret talks, yet they ˹always˺ return to what they were forbidden from, conspiring in sin, aggression, and disobedience to the Messenger? And when they come to you ˹O Prophet˺, they greet you not as Allah greets you, and say to one another, “Why does Allah not punish us for what we say?” Hell is enough for them—they will burn in it. And what an evil destination','क्या तुमने उन लोगों को नहीं देखा जिनको सरगोशियाँ करने से मना किया गया ग़रज़ जिस काम की उनको मुमानिअत की गयी थी उसी को फिर करते हैं और (लुत्फ़ तो ये है कि) गुनाह और (बेजा) ज्यादती और रसूल की नाफरमानी की सरगोशियाँ करते हैं और जब तुम्हारे पास आते हैं तो जिन लफ्ज़ों से ख़ुदा ने भी तुम को सलाम नहीं किया उन लफ्ज़ों से सलाम करते हैं और अपने जी में कहते हैं कि (अगर ये वाक़ई पैग़म्बर हैं तो) जो कुछ हम कहते हैं ख़ुदा हमें उसकी सज़ा क्यों नहीं देता (ऐ रसूल) उनको दोज़ख़ ही (की सज़ा) काफी है जिसमें ये दाख़िल होंगे तो वह (क्या) बुरी जगह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,9,'Al-Mujaadila','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوۡاْ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ','مومنو! جب تم آپس میں سرگوشیاں کرنے لگو تو گناہ اور زیادتی اور پیغمبر کی نافرمانی کی باتیں نہ کرنا بلکہ نیکوکاری اور پرہیزگاری کی باتیں کرنا۔ اور خدا سے جس کے سامنے جمع کئے جاؤ گے ڈرتے رہنا','O believers! When you converse privately, let it not be for sin, aggression, or disobedience to the Messenger, but let it be for goodness and righteousness. And fear Allah, to Whom you will ˹all˺ be gathered','ऐ ईमानदारों जब तुम आपस में सरगोशी करो तो गुनाह और ज्यादती और रसूल की नाफरमानी की सरगोशी न करो बल्कि नेकीकारी और परहेज़गारी की सरगोशी करो और ख़ुदा से डरते रहो जिसके सामने (एक दिन) जमा किए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,10,'Al-Mujaadila','إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ لِيَحۡزُنَ ٱلَّذِينَ ءَامَنُواْ وَلَيۡسَ بِضَآرِّهِمۡ شَيۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ','(کافروں کی) سرگوشیاں تو شیطان (کی حرکات) سے ہیں (جو) اس لئے (کی جاتی ہیں) کہ مومن (ان سے) غمناک ہوں مگر خدا کے حکم کے سوا ان سے انہیں کچھ نقصان نہیں پہنچ سکتا۔ تو مومنو کو چاہیئے کہ خدا ہی پر بھروسہ رکھیں','Secret talks are only inspired by Satan to grieve the believers. Yet he cannot harm them whatsoever except by Allah’s Will. So in Allah let the believers put their trust','(बरी बातों की) सरगोशी तो बस एक शैतानी काम है (और इसलिए करते हैं) ताकि ईमानदारों को उससे रंज पहुँचे हालॉकि ख़ुदा की तरफ से आज़ादी दिए बग़ैर सरगोशी उनका कुछ बिगाड़ नहीं सकती और मोमिनीन को तो ख़ुदा ही पर भरोसा रखना चाहिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,11,'Al-Mujaadila','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتࣲۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ‏','مومنو! جب تم سے کہا جائے کہ مجلس میں کھل کر بیٹھو تو کھل بیٹھا کرو۔ خدا تم کو کشادگی بخشے گا۔ اور جب کہا جائے کہ اُٹھ کھڑے ہو تو اُٹھ کھڑے ہوا کرو۔ جو لوگ تم میں سے ایمان لائے ہیں اور جن کو علم عطا کیا گیا ہے خدا ان کے درجے بلند کرے گا۔ اور خدا تمہارے سب کاموں سے واقف ہے','O believers! When you are told to make room in gatherings, then do so. Allah will make room for you ˹in His grace˺. And if you are told to rise, then do so. Allah will elevate those of you who are faithful, and ˹raise˺ those gifted with knowledge in rank. And Allah is All-Aware of what you do','ऐ ईमानदारों जब तुमसे कहा जाए कि मजलिस में जगह कुशादा करो वह तो कुशादा कर दिया करो ख़ुदा तुमको कुशादगी अता करेगा और जब तुमसे कहा जाए कि उठ खड़े हो तो उठ खड़े हुआ करो जो लोग तुमसे ईमानदार हैं और जिनको इल्म अता हुआ है ख़ुदा उनके दर्जे बुलन्द करेगा और ख़ुदा तुम्हारे सब कामों से बेख़बर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,12,'Al-Mujaadila','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَٰجَيۡتُمُ ٱلرَّسُولَ فَقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَةࣰۚ ذَٰلِكَ خَيۡرࣱ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُواْ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ','مومنو! جب تم پیغمبر کے کان میں کوئی بات کہو تو بات کہنے سے پہلے (مساکین کو) کچھ خیرات دے دیا کرو۔ یہ تمہارے لئے بہت بہتر اور پاکیزگی کی بات ہے۔ اور اگر خیرات تم کو میسر نہ آئے تو خدا بخشنے والا مہربان ہے','O believers! When you consult the Messenger privately, give something in charity before your consultation. That is better and purer for you. But if you lack the means, then Allah is truly All-Forgiving, Most Merciful','ऐ ईमानदारों जब पैग़म्बर से कोई बात कान में कहनी चाहो तो कुछ ख़ैरात अपनी सरगोशी से पहले दे दिया करो यही तुम्हारे वास्ते बेहतर और पाकीज़ा बात है पस अगर तुमको इसका मुक़दूर न हो तो बेशक ख़ुदा बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,13,'Al-Mujaadila','ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُواْ بَيۡنَ يَدَيۡ نَجۡوَىٰكُمۡ صَدَقَٰتࣲۚ فَإِذۡ لَمۡ تَفۡعَلُواْ وَتَابَ ٱللَّهُ عَلَيۡكُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ','کیا تم اس سےکہ پیغمبر کے کان میں کوئی بات کہنے سے پہلے خیرات دیا کرو ڈر گئے؟ پھر جب تم نے (ایسا) نہ کیا اور خدا نے تمہیں معاف کردیا تو نماز پڑھتے اور زکوٰة دیتے رہو اور خدا اور اس کے رسول کی فرمانبرداری کرتے رہو۔ اور جو کچھ تم کرتے ہو خدا اس سے خبردار ہے','Are you afraid of spending in charity before your private consultations ˹with him˺? Since you are unable to do so, and Allah has turned to you in mercy, then ˹continue to˺ establish prayer, pay alms-tax, and obey Allah and His Messenger. And Allah is All-Aware of what you do','(मुसलमानों) क्या तुम इस बात से डर गए कि (रसूल के) कान में बात कहने से पहले ख़ैरात कर लो तो जब तुम लोग (इतना सा काम) न कर सके और ख़ुदा ने तुम्हें माफ़ कर दिया तो पाबन्दी से नमाज़ पढ़ो और ज़कात देते रहो और ख़ुदा उसके रसूल की इताअत करो और जो कुछ तुम करते हो ख़ुदा उससे बाख़बर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,14,'Al-Mujaadila','۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ يَعۡلَمُونَ','بھلا تم نے ان لوگوں کو نہیں دیکھا جو ایسوں سے دوستی کرتے ہیں جن پر خدا کا غضب ہوا۔ وہ نہ تم میں ہیں نہ ان میں۔ اور جان بوجھ کر جھوٹی باتوں پر قسمیں کھاتے ہیں','Have you not seen those ˹hypocrites˺ who ally themselves with a people with whom Allah is displeased? They are neither with you nor with them. And they swear to lies knowingly','क्या तुमने उन लोगों की हालत पर ग़ौर नहीं किया जो उन लोगों से दोस्ती करते हैं जिन पर ख़ुदा ने ग़ज़ब ढाया है तो अब वह न तुम मे हैं और न उनमें ये लोग जानबूझ कर झूठी बातो पर क़समें खाते हैं और वह जानते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,15,'Al-Mujaadila','أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰ ا شَدِيدًاۖ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ','خدا نے ان کے لئے سخت عذاب تیار کر رکھا ہے۔ یہ جو کچھ کرتے ہیں یقیناً برا ہے','Allah has prepared for them a severe punishment. Evil indeed is what they do','ख़ुदा ने उनके लिए सख्त अज़ाब तैयार कर रखा है इसमें शक़ नहीं कि ये लोग जो कुछ करते हैं बहुत ही बुरा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,16,'Al-Mujaadila','ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةࣰ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِ فَلَهُمۡ عَذَابࣱ مُّهِينࣱ‏','انہوں نے اپنی قسموں کو ڈھال بنا لیا اور (لوگوں کو) خدا کے راستے سے روک دیا ہے سو ان کے لئے ذلت کا عذاب ہے','They have made their ˹false˺ oaths as a shield, hindering ˹others˺ from the cause of Allah. So they will suffer a humiliating punishment','उन लोगों ने अपनी क़समों को सिपर बना लिया है और (लोगों को) ख़ुदा की राह से रोक दिया तो उनके लिए रूसवा करने वाला अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,17,'Al-Mujaadila','لَّن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','خدا کے (عذاب کے) سامنے نہ تو ان کا مال ہی کچھ کام آئے گا اور نہ اولاد ہی (کچھ فائدہ دے گی) ۔ یہ لوگ اہل دوزخ ہیں اس میں ہمیشہ (جلتے) رہیں گے','Neither their wealth nor children will be of any help to them against Allah whatsoever. It is they who will be the residents of the Fire. They will be there forever','ख़ुदा सामने हरगिज़ न उनके माल ही कुछ काम आएँगे और न उनकी औलाद ही काम आएगी यही लोग जहन्नुमी हैं कि हमेशा उसमें रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,18,'Al-Mujaadila','يَوۡمَ يَبۡعَثُهُمُ ٱللَّهُ جَمِيعࣰ ا فَيَحۡلِفُونَ لَهُۥ كَمَا يَحۡلِفُونَ لَكُمۡ وَيَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَيۡءٍۚ أَلَآ إِنَّهُمۡ هُمُ ٱلۡكَٰذِبُونَ','جس دن خدا ان سب کو جلا اٹھائے گا تو جس طرح تمہارے سامنے قسمیں کھاتے (اسی طرح) خدا کے سامنے قسمیں کھائیں گے اور خیال کریں گے کہ (ایسا کرنے سے) کام لے نکلے ہیں۔ دیکھو یہ جھوٹے (اور برسر غلط) ہیں','On the Day Allah resurrects them all, they will ˹falsely˺ swear to Him as they swear to you, thinking they have something to stand on. Indeed, it is they who are the ˹total˺ liars','जिस दिन ख़ुदा उन सबको दोबार उठा खड़ा करेगा तो ये लोग जिस तरह तुम्हारे सामने क़समें खाते हैं उसी तरह उसके सामने भी क़समें खाएँगे और ख्याल करते हैं कि वह राहे सवाब पर हैं आगाह रहो ये लोग यक़ीनन झूठे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,19,'Al-Mujaadila','ٱسۡتَحۡوَذَ عَلَيۡهِمُ ٱلشَّيۡطَٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُوْلَٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ أَلَآ إِنَّ حِزۡبَ ٱلشَّيۡطَٰنِ هُمُ ٱلۡخَٰسِرُونَ','شیطان نے ان کو قابو میں کرلیا ہے۔ اور خدا کی یاد ان کو بھلا دی ہے۔ یہ (جماعت) شیطان کا لشکر ہے۔ اور سن رکھو کہ شیطان کا لشکر نقصان اٹھانے والا ہے','Satan has taken hold of them, causing them to forget the remembrance of Allah. They are the party of Satan. Surely Satan’s party is bound to lose','शैतान ने इन पर क़ाबू पा लिया है और ख़ुदा की याद उनसे भुला दी है ये लोग शैतान के गिरोह है सुन रखो कि शैतान का गिरोह घाटा उठाने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,20,'Al-Mujaadila','إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُوْلَٰٓئِكَ فِي ٱلۡأَذَلِّينَ','جو لوگ خدا اور اس کے رسول کی مخالفت کرتے ہیں وہ نہایت ذلیل ہوں گے','˹As for˺ those who defy Allah and His Messenger, they will definitely be among the most debased','जो लोग ख़ुदा और उसके रसूल से मुख़ालेफ़त करते हैं वह सब ज़लील लोगों में हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,21,'Al-Mujaadila','كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزࣱ‏','خدا کا حکم ناطق ہے کہ میں اور میرے پیغمبر ضرور غالب رہیں گے۔ بےشک خدا زورآور (اور) زبردست ہے','Allah has decreed, “I and My messengers will certainly prevail.” Surely Allah is All-Powerful, Almighty','ख़ुदा ने हुक्म नातिक दे दिया है कि मैं और मेरे पैग़म्बर ज़रूर ग़ालिब रहेंगे बेशक ख़ुदा बड़ा ज़बरदस्त ग़ालिब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (58,22,'Al-Mujaadila','لَّا تَجِدُ قَوۡمࣰ ا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوٓاْ ءَابَآءَهُمۡ أَوۡ أَبۡنَآءَهُمۡ أَوۡ إِخۡوَٰنَهُمۡ أَوۡ عَشِيرَتَهُمۡۚ أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ وَأَيَّدَهُم بِرُوحࣲ مِّنۡهُۖ وَيُدۡخِلُهُمۡ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ رَضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ أُوْلَٰٓئِكَ حِزۡبُ ٱللَّهِۚ أَلَآ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ','جو لوگ خدا پر اور روز قیامت پر ایمان رکھتے ہیں تم ان کو خدا اور اس کے رسول کے دشمنوں سے دوستی کرتے ہوئے نہ دیکھو گے۔ خواہ وہ ان کے باپ یا بیٹے یا بھائی یا خاندان ہی کے لوگ ہوں۔ یہ وہ لوگ ہیں جن کے دلوں میں خدا نے ایمان (پتھر پر لکیر کی طرح) تحریر کردیا ہے اور فیض غیبی سے ان کی مدد کی ہے۔ اور وہ ان کو بہشتوں میں جن کے تلے نہریں بہہ رہی ہیں داخل کرے گا ہمیشہ ان میں رہیں گے۔ خدا ان سے خوش اور وہ خدا سے خوش۔ یہی گروہ خدا کا لشکر ہے۔ (اور) سن رکھو کہ خدا ہی کا لشکر مراد حاصل کرنے والا ہے','You will never find a people who ˹truly˺ believe in Allah and the Last Day loyal to those who defy Allah and His Messenger, even if they were their parents, children, siblings, or extended family. For those ˹believers˺, Allah has instilled faith in their hearts and strengthened them with a spirit from Him. He will admit them into Gardens under which rivers flow, to stay there forever. Allah is pleased with them and they are pleased with Him. They are the party of Allah. Indeed, Allah’s party is bound to succeed','जो लोग ख़ुदा और रोज़े आख़ेरत पर ईमान रखते हैं तुम उनको ख़ुदा और उसके रसूल के दुश्मनों से दोस्ती करते हुए न देखोगे अगरचे वह उनके बाप या बेटे या भाई या ख़ानदान ही के लोग (क्यों न हों) यही वह लोग हैं जिनके दिलों में ख़ुदा ने ईमान को साबित कर दिया है और ख़ास अपने नूर से उनकी ताईद की है और उनको (बेहिश्त में) उन (हरे भरे) बाग़ों में दाखिल करेगा जिनके नीचे नहरे जारी है (और वह) हमेश उसमें रहेंगे ख़ुदा उनसे राज़ी और वह ख़ुदा से ख़ुश यही ख़ुदा का गिरोह है सुन रखो कि ख़ुदा के गिरोग के लोग दिली मुरादें पाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,1,'Al-Hashr','سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','جو چیزیں آسمانوں میں ہیں اور جو چیزیں زمین میں ہیں (سب) خدا کی تسبیح کرتی ہیں۔ اور وہ غالب حکمت والا ہے','Whatever is in the heavens and whatever is on the earth glorifies Allah. For He is the Almighty, All-Wise','जो चीज़ आसमानों में है और जो चीज़ ज़मीन में है (सब) ख़ुदा की तस्बीह करती हैं और वही ग़ालिब हिकमत वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,2,'Al-Hashr','هُوَ ٱلَّذِيٓ أَخۡرَجَ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن دِيَٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن يَخۡرُجُواْۖ وَظَنُّوٓاْ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَۚ يُخۡرِبُونَ بُيُوتَهُم بِأَيۡدِيهِمۡ وَأَيۡدِي ٱلۡمُؤۡمِنِينَ فَٱعۡتَبِرُواْ يَٰٓأُوْلِي ٱلۡأَبۡصَٰرِ','وہی تو ہے جس نے کفار اہل کتاب کو حشر اول کے وقت ان کے گھروں سے نکال دیا۔ تمہارے خیال میں بھی نہ تھا کہ وہ نکل جائیں گے اور وہ لوگ یہ سمجھے ہوئے تھے کہ ان کے قلعے ان کو خدا (کے عذاب) سے بچا لیں گے۔ مگر خدا نے ان کو وہاں سے آ لیا جہاں سے ان کو گمان بھی نہ تھا۔ اور ان کے دلوں میں دہشت ڈال دی کہ اپنے گھروں کو خود اپنے ہاتھوں اور مومنوں کے ہاتھوں سے اُجاڑنے لگے تو اے (بصیرت کی) آنکھیں رکھنے والو عبرت پکڑو','He is the One Who expelled the disbelievers of the People of the Book from their homes for ˹their˺ first banishment ˹ever˺. You never thought they would go. And they thought their strongholds would put them out of Allah’s reach. But ˹the decree of˺ Allah came upon them from where they never expected. And He cast horror into their hearts so they destroyed their houses with their own hands and the hands of the believers. So take a lesson ˹from this˺, O people of insight','वही तो है जिसने कुफ्फ़ार अहले किताब (बनी नुजैर) को पहले हश्र (ज़िलाए वतन) में उनके घरों से निकाल बाहर किया (मुसलमानों) तुमको तो ये वहम भी न था कि वह निकल जाएँगे और वह लोग ये समझे हुये थे कि उनके क़िले उनको ख़ुदा (के अज़ाब) से बचा लेंगे मगर जहाँ से उनको ख्याल भी न था ख़ुदा ने उनको आ लिया और उनके दिलों में (मुसलमानों) को रौब डाल दिया कि वह लोग ख़ुद अपने हाथों से और मोमिनीन के हाथों से अपने घरों को उजाड़ने लगे तो ऐ ऑंख वालों इबरत हासिल करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,3,'Al-Hashr','وَلَوۡلَآ أَن كَتَبَ ٱللَّهُ عَلَيۡهِمُ ٱلۡجَلَآءَ لَعَذَّبَهُمۡ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابُ ٱلنَّارِ','اور اگر خدا نے ان کے بارے میں جلاوطن کرنا نہ لکھ رکھا ہوتا تو ان کو دنیا میں بھی عذاب دے دیتا۔ اور آخرت میں تو ان کے لئے آگ کا عذاب (تیار) ہے','Had Allah not decreed exile for them, He would have certainly punished them in this world. And in the Hereafter they will suffer the punishment of the Fire','और ख़ुदा ने उनकी किसमत में ज़िला वतनी न लिखा होता तो उन पर दुनिया में भी (दूसरी तरह) अज़ाब करता और आख़ेरत में तो उन पर जहन्नुम का अज़ाब है ही');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,4,'Al-Hashr','ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','یہ اس لئے کہ انہوں نے خدا اور اس کے رسول کی مخالفت کی۔ اور جو شخص خدا کی مخالفت کرے تو خدا سخت عذاب دینے والا ہے','This is because they defied Allah and His Messenger. And whoever defies Allah, then Allah is truly severe in punishment','ये इसलिए कि उन लोगों ने ख़ुदा और उसके रसूल की मुख़ालेफ़त की और जिसने ख़ुदा की मुख़ालेफ़त की तो (याद रहे कि) ख़ुदा बड़ा सख्त अज़ाब देने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,5,'Al-Hashr','مَا قَطَعۡتُم مِّن لِّينَةٍ أَوۡ تَرَكۡتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِيُخۡزِيَ ٱلۡفَٰسِقِينَ','(مومنو) کھجور کے جو درخت تم نے کاٹ ڈالے یا ان کو اپنی جڑوں پر کھڑا رہنے دیا سو خدا کے حکم سے تھا اور مقصود یہ تھا کہ وہ نافرمانوں کو رسوا کرے','Whatever palm trees you ˹believers˺ cut down or left standing intact, it was ˹all˺ by Allah’s Will, so that He might disgrace the rebellious','(मोमिनों) खजूर का दरख्त जो तुमने काट डाला या जूँ का तँ से उनकी जड़ों पर खड़ा रहने दिया तो ख़ुदा ही के हुक्म से और मतलब ये था कि वह नाफरमानों को रूसवा करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,6,'Al-Hashr','وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَآ أَوۡجَفۡتُمۡ عَلَيۡهِ مِنۡ خَيۡلࣲ وَلَا رِكَابࣲ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','اور جو (مال) خدا نے اپنے پیغمبر کو ان لوگوں سے (بغیر لڑائی بھڑائی کے) دلوایا ہے اس میں تمہارا کچھ حق نہیں کیونکہ اس کے لئے نہ تم نے گھوڑے دوڑائے نہ اونٹ لیکن خدا اپنے پیغمبروں کو جن پر چاہتا ہے مسلط کردیتا ہے۔ اور خدا ہر چیز پر قادر ہے','As for the gains Allah has turned over to His Messenger from them—you did not ˹even˺ spur on any horse or camel for such gains. But Allah gives authority to His messengers over whoever He wills. For Allah is Most Capable of everything','(तो) जो माल ख़ुदा ने अपने रसूल को उन लोगों से बे लड़े दिलवा दिया उसमें तुम्हार हक़ नहीं क्योंकि तुमने उसके लिए कुछ दौड़ धूप तो की ही नहीं, न घोड़ों से न ऊँटों से, मगर ख़ुदा अपने पैग़म्बरों को जिस पर चाहता है ग़लबा अता फरमाता है और ख़ुदा हर चीज़ पर क़ादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,7,'Al-Hashr','مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ كَيۡ لَا يَكُونَ دُولَةَۢ بَيۡنَ ٱلۡأَغۡنِيَآءِ مِنكُمۡۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُواْۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ','جو مال خدا نے اپنے پیغمبر کو دیہات والوں سے دلوایا ہے وہ خدا کے اور پیغمبر کے اور (پیغمبر کے) قرابت والوں کے اور یتیموں کے اور حاجتمندوں کے اور مسافروں کے لئے ہے۔ تاکہ جو لوگ تم میں دولت مند ہیں ان ہی کے ہاتھوں میں نہ پھرتا رہے۔ سو جو چیز تم کو پیغمبر دیں وہ لے لو۔ اور جس سے منع کریں (اس سے) باز رہو۔ اور خدا سے ڈرتے رہو۔ بےشک خدا سخت عذاب دینے والا ہے','As for gains granted by Allah to His Messenger from the people of ˹other˺ lands, they are for Allah and the Messenger, his close relatives, orphans, the poor, and ˹needy˺ travellers so that wealth may not merely circulate among your rich. Whatever the Messenger gives you, take it. And whatever he forbids you from, leave it. And fear Allah. Surely Allah is severe in punishment','तो जो माल ख़ुदा ने अपने रसूल को देहात वालों से बे लड़े दिलवाया है वह ख़ास ख़ुदा और उसके रसूल और (रसूल के) क़राबतदारों और यतीमों और मोहताजों और परदेसियों का है ताकि जो लोग तुममें से दौलतमन्द हैं हिर फिर कर दौलत उन्हीं में न रहे, हाँ जो तुमको रसूल दें दें वह ले लिया करो और जिससे मना करें उससे बाज़ रहो और ख़ुदा से डरते रहो बेशक ख़ुदा सख्त अज़ाब देने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,8,'Al-Hashr','لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ يَبۡتَغُونَ فَضۡلࣰ ا مِّنَ ٱللَّهِ وَرِضۡوَٰنࣰ ا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ','(اور) ان مفلسان تارک الوطن کے لئے بھی جو اپنے گھروں اور مالوں سے خارج (اور جدا) کر دیئے گئے ہیں (اور) خدا کے فضل اور اس کی خوشنودی کے طلبگار اور خدا اور اس کے پیغمبر کے مددگار ہیں۔ یہی لوگ سچے (ایماندار) ہیں','˹Some of the gains will be˺ for poor emigrants who were driven out of their homes and wealth, seeking Allah’s bounty and pleasure, and standing up for Allah and His Messenger. They are the ones true in faith','(इस माल में) उन मुफलिस मुहाजिरों का हिस्सा भी है जो अपने घरों से और मालों से निकाले (और अलग किए) गए (और) ख़ुदा के फ़ज़ल व ख़ुशनूदी के तलबगार हैं और ख़ुदा की और उसके रसूल की मदद करते हैं यही लोग सच्चे ईमानदार हैं और (उनका भी हिस्सा है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (59,9,'Al-Hashr','وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةࣰ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةࣱۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','اور (ان لوگوں کے لئے بھی) جو مہاجرین سے پہلے (ہجرت کے) گھر (یعنی مدینے) میں مقیم اور ایمان میں (مستقل) رہے (اور) جو لوگ ہجرت کرکے ان کے پاس آتے ہیں ان سے محبت کرتے ہیں اور جو کچھ ان کو ملا اس سے اپنے دل میں کچھ خواہش (اور خلش) نہیں پاتے اور ان کو اپنی جانوں سے مقدم رکھتے ہیں خواہ ان کو خود احتیاج ہی ہو۔ اور جو شخص حرص نفس سے بچا لیا گیا تو ایسے لوگ مراد پانے والے ہیں','As for those who had settled in the city and ˹embraced˺ the faith before ˹the arrival of˺ the emigrants, they love whoever immigrates to them, never having a desire in their hearts for whatever ˹of the gains˺ is given to the emigrants. They give ˹the emigrants˺ preference over themselves even though they may be in need. And whoever is saved from the selfishness of their own souls, it is they who are ˹truly˺ successful','जो लोग मोहाजेरीन से पहले (हिजरत के) घर (मदीना) में मुक़ीम हैं और ईमान में (मुसतक़िल) रहे और जो लोग हिजरत करके उनके पास आए उनसे मोहब्बत करते हैं और जो कुछ उनको मिला उसके लिए अपने दिलों में कुछ ग़रज़ नहीं पाते और अगरचे अपने ऊपर तंगी ही क्यों न हो दूसरों को अपने नफ्स पर तरजीह देते हैं और जो शख़्श अपने नफ्स की हिर्स से बचा लिया गया तो ऐसे ही लोग अपनी दिली मुरादें पाएँगे');
